local DeltaStorage=(function()
    local API={folder="DeltaClient"}
    local json=game:GetService("HttpService")
    function API.UserId()
        local player=game:GetService("Players").LocalPlayer
        return player and tostring(player.UserId) or ""
    end
    function API.Read(name)
        if type(isfile)~="function" or type(readfile)~="function" then return nil end
        local ok,value=pcall(function()
            local path=API.folder.."/"..name
            if not isfile(path) then return nil end
            local raw=readfile(path)
            if type(raw)~="string" or #raw>16384 then return nil end
            local decoded=json:JSONDecode(raw)
            return type(decoded)=="table" and decoded or nil
        end)
        return ok and value or nil
    end
    function API.Write(name,data)
        if type(isfolder)~="function" or type(makefolder)~="function" or type(writefile)~="function"
            or type(isfile)~="function" or type(readfile)~="function" then return false end
        local ok=pcall(function()
            if not isfolder(API.folder) then makefolder(API.folder) end
            local path=API.folder.."/"..name
            local raw=json:JSONEncode(data)
            writefile(path,raw)
            assert(isfile(path) and readfile(path)==raw,"Storage verification failed")
        end)
        return ok
    end
    return API
end)()

