    ["Aimbot Enabled"]="Aimbot",["Aim Assist Enabled"]="Aim Assist",["Triggerbot Enabled"]="Triggerbot",
    ["Player ESP"]="Player ESP",["NPC ESP"]="NPC ESP",Fullbright="Fullbright",FriendNoTrigger="FriendNoTrigger",
