    NativeStartButton=NativeButton(header,"Start functions",30);NativeStartButton.Position=UDim2.new(1,-235,0,12);NativeStartButton.Size=UDim2.new(0,150,0,30)
    NativeConnect(NativeStartButton.Activated,function() NativeStart(not RuntimeReady) end)
    local hide=NativeButton(header,"K",30);hide.Position=UDim2.new(1,-76,0,12);hide.Size=UDim2.new(0,28,0,30)
    local close=NativeButton(header,"X",30);close.Position=UDim2.new(1,-40,0,12);close.Size=UDim2.new(0,28,0,30)
