        local heading=NativeText(card,name,32);heading.Font=Enum.Font.GothamSemibold;heading.TextSize=12;heading.TextColor3=Color3.fromRGB(111,205,237)
        heading.Position=UDim2.new(0,12,0,0);heading.Size=UDim2.new(1,-24,0,32)
