            or (name=="FreeCam" or name=="NoClip" or name=="Infinite Jump" or name=="Fly" or name=="Speed") and "Movement"
            or (name=="Player ESP" or name=="NPC ESP" or name=="World") and "Visuals" or name=="Config" and "Config" or "Settings"
