        end
        function tab:CreateDropdown(options)
            local container=row(NativeMake("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,36)},content))
            local button=NativeButton(container,"",36)
            local list=NativeMake("ScrollingFrame",{BackgroundColor3=Color3.fromRGB(13,35,48),BorderSizePixel=0,
                Position=UDim2.new(0,0,0,40),Size=UDim2.new(1,0,0,120),CanvasSize=UDim2.new(0,0,0,0),ScrollBarThickness=3,Visible=false},container)
            NativeRound(list,6)
            local handle={CurrentOption=options.CurrentOption or {},Options=options.Options or {}}
            local items={}
            local function paint() button.Text=options.Name..": "..tostring(handle.CurrentOption[1] or "-").."   v" end
            local function collapse() list.Visible=false;container.Size=UDim2.new(1,0,0,36) end
            function handle:Set(value)
                self.CurrentOption=type(value)=="table" and value or {value};paint();collapse()
                if options.Callback then options.Callback(self.CurrentOption) end
            end
            function handle:Refresh(values)
                self.Options=values
                for _,item in ipairs(items) do item:Destroy() end;items={}
