                    local choice=value
                    local item=NativeButton(list,tostring(value),27);item.Position=UDim2.new(0,0,0,(index-1)*29);item.Size=UDim2.new(1,-5,0,27)
                    NativeConnect(item.Activated,function() handle:Set({choice}) end);table.insert(items,item)
                end
                list.CanvasSize=UDim2.new(0,0,0,#values*29)
                local height=math.min(174,#values*29);list.Size=UDim2.new(1,0,0,height)
                if list.Visible then container.Size=UDim2.new(1,0,0,44+height) end
