        end
        function tab:CreateSlider(options)
            local container=row(NativeMake("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,62)},content))
            local label=NativeText(container,options.Name,24);label.Size=UDim2.new(1,-80,0,24)
            local valueBox=NativeMake("TextBox",{Text="",ClearTextOnFocus=false,TextSize=10,Font=Enum.Font.Gotham,
                TextColor3=Color3.fromRGB(130,215,242),BackgroundColor3=Color3.fromRGB(16,48,65),BorderSizePixel=0,
                Position=UDim2.new(1,-74,0,0),Size=UDim2.new(0,74,0,25)},container);NativeRound(valueBox,5)
            local track=NativeButton(container,"",18);track.Position=UDim2.new(0,0,0,34)
            local fill=NativeMake("Frame",{BackgroundColor3=Color3.fromRGB(55,163,199),BorderSizePixel=0,Size=UDim2.new(0,0,1,0)},track);NativeRound(fill,6)
            local low,high=options.Range[1],options.Range[2]
