            function handle:Set(value)
                value=tonumber(value) or self.CurrentValue
                value=math.max(low,math.min(high,low+math.floor((value-low)/step+.5)*step))
                self.CurrentValue=value;paint();if options.Callback then options.Callback(value) end
            end
            local dragging=false
            local function fromPoint(point)
                local width=track.AbsoluteSize.X
                if width>0 then handle:Set(low+math.max(0,math.min(1,(point.X-track.AbsolutePosition.X)/width))*(high-low)) end
            end
            NativeConnect(track.InputBegan,function(input)
                if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
                    dragging=true;NativeInteracting=true;fromPoint(input.Position)
                end
            end)
            NativeConnect(NativeUIS.InputChanged,function(input)
                if dragging and (input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch) then fromPoint(input.Position) end
            end)
            NativeConnect(NativeUIS.InputEnded,function(input)
                if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=false;NativeInteracting=false end
            end)
            NativeConnect(valueBox.FocusLost,function() handle:Set(valueBox.Text) end)
            paint();return register(options,handle)
        end
        return tab
    end
    return window
end
local NativeVisuals={}
function NativeVisuals.new(kind)
    if not NativeVisualRoot then
        NativeVisualRoot=NativeMake("ScreenGui",{Name="Visuals",IgnoreGuiInset=true,ResetOnSpawn=false,DisplayOrder=20},NativeParent)
    end
    local frame=NativeMake(kind=="Text" and "TextLabel" or "Frame",{Visible=false,BackgroundTransparency=1,BorderSizePixel=0},NativeVisualRoot)
    local stroke
    if kind=="Square" or kind=="Circle" then stroke=NativeMake("UIStroke",{Thickness=1},frame) end
    if kind=="Circle" then NativeMake("UICorner",{CornerRadius=UDim.new(1,0)},frame) end
    if kind=="Text" then frame.Font=Enum.Font.Gotham;frame.TextSize=14;frame.TextStrokeTransparency=0 end
    local properties={Visible=false,Position=Vector2.new(0,0),Size=kind=="Text" and 14 or Vector2.new(0,0),
        Radius=0,Thickness=1,Color=Color3.fromRGB(255,255,255),Transparency=1,From=Vector2.new(0,0),To=Vector2.new(0,0)}
    local object
    local function paint()
        frame.Visible=properties.Visible
        local alpha=1-math.max(0,math.min(1,properties.Transparency))
        if kind=="Text" then
            frame.BackgroundTransparency=1;frame.Text=properties.Text or "";frame.TextColor3=properties.Color
            frame.TextTransparency=alpha;frame.TextSize=properties.Size;frame.TextStrokeTransparency=properties.Outline and alpha or 1
            frame.AnchorPoint=Vector2.new(properties.Center and .5 or 0,0)
            frame.Position=UDim2.new(0,properties.Position.X,0,properties.Position.Y);frame.Size=UDim2.new(0,420,0,properties.Size+8)
            frame.TextXAlignment=properties.Center and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left
        elseif kind=="Line" then
            local delta=properties.To-properties.From
            frame.AnchorPoint=Vector2.new(.5,.5);frame.Position=UDim2.new(0,(properties.From.X+properties.To.X)/2,0,(properties.From.Y+properties.To.Y)/2)
            frame.Size=UDim2.new(0,delta.Magnitude,0,properties.Thickness);frame.Rotation=math.deg(math.atan2(delta.Y,delta.X))
            frame.BackgroundColor3=properties.Color;frame.BackgroundTransparency=alpha
        else
            local radius=properties.Radius
            local width=kind=="Circle" and radius*2 or properties.Size.X
            local height=kind=="Circle" and radius*2 or properties.Size.Y
            frame.Position=UDim2.new(0,properties.Position.X-(kind=="Circle" and radius or 0),0,properties.Position.Y-(kind=="Circle" and radius or 0))
            frame.Size=UDim2.new(0,width,0,height);frame.BackgroundColor3=properties.Color
            frame.BackgroundTransparency=properties.Filled and alpha or 1
            stroke.Color=properties.Color;stroke.Thickness=properties.Thickness;stroke.Transparency=alpha
        end
    end
    object=setmetatable({}, {__index=function(_,key)
        if key=="Remove" then return function() frame:Destroy();NativeShapes[object]=nil end end
        return properties[key]
    end,__newindex=function(_,key,value)
        if properties[key]~=value then properties[key]=value;NativeShapes[object].dirty=true end
    end})
    NativeShapes[object]={frame=frame,paint=paint,dirty=true};return object
end

local function NativeFlushVisuals()
    if not RuntimeReady then return end
    for _,shape in pairs(NativeShapes) do
        if shape.dirty and shape.frame.Parent then shape.paint();shape.dirty=false end
    end
end
