-- Local movement controller. No downloaded dependencies or workspace traversal.
local Movement=(function()
    local API={}
    local free,fly,speed,noclip
    local focused=true
    local nextJump=0
    local captureGuard=function() return false end
    local renderName="DEV_HUB_FreeCam"
    local renderBound=false
    local renderFallback
    local currentCharacter
    local lastError=""
    local zero=Vector3.new(0,0,0)
    local function put(object,property,value)
        if object then pcall(function() object[property]=value end) end
    end
    local function destroy(object) if object then pcall(function() object:Destroy() end) end end
    local function characterParts()
        local character=LocalPlayer.Character
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        local root=character and character:FindFirstChild("HumanoidRootPart")
        if not humanoid or humanoid.Health<=0 or not root then return character,nil,nil end
        return character,humanoid,root
    end
    local function acceptsInput()
        return focused and not Native.SystemMenuOpen() and not Native.IsInteracting()
            and not UserInputService:GetFocusedTextBox() and not captureGuard()
            and not (Native.MenuFrame() and Native.MenuFrame().Visible)
    end
    local function down(key) return UserInputService:IsKeyDown(key) and 1 or 0 end
    local function direction(camera)
        if not camera or not acceptsInput() then return zero end
        local x=down(Enum.KeyCode.D)-down(Enum.KeyCode.A)
        local z=down(Enum.KeyCode.W)-down(Enum.KeyCode.S)
        local y=math.max(down(Enum.KeyCode.Space),down(Enum.KeyCode.E))
            -math.max(down(Enum.KeyCode.LeftControl),down(Enum.KeyCode.Q))
        local value=camera.CFrame.RightVector*x+camera.CFrame.LookVector*z+Vector3.new(0,y,0)
        local length=value.Magnitude
        return length>1 and value/length or value
    end
    local function stopSpeed()
        if not speed then return end
        put(speed.humanoid,"WalkSpeed",speed.original)
        speed=nil
    end
    local function stopNoClip()
        if not noclip then return end
        if noclip.added then noclip.added:Disconnect() end
        for part,original in pairs(noclip.parts) do put(part,"CanCollide",original) end
        noclip=nil
    end
    local function stopFly()
        if not fly then return end
        for _,object in ipairs(fly.objects) do destroy(object) end
        put(fly.humanoid,"AutoRotate",fly.autoRotate)
        put(fly.humanoid,"PlatformStand",fly.platformStand)
        if not fly.platformStand then pcall(function() fly.humanoid:ChangeState(Enum.HumanoidStateType.GettingUp) end) end
        put(fly.root,"AssemblyLinearVelocity",zero)
        fly=nil
    end
    local function stopFreeCam()
        if renderBound then pcall(function() RunService:UnbindFromRenderStep(renderName) end);renderBound=false end
        if renderFallback then renderFallback:Disconnect();renderFallback=nil end
        if not free then return end
        put(free.root,"Anchored",free.anchored)
        put(free.root,"AssemblyLinearVelocity",zero)
        put(free.humanoid,"AutoRotate",free.autoRotate)
        put(free.camera,"CameraType",free.cameraType)
        put(free.camera,"CFrame",free.cameraCFrame)
        put(free.camera,"Focus",free.cameraFocus)
        local subject=free.subject
        if subject and subject.Parent then put(free.camera,"CameraSubject",subject) end
        put(UserInputService,"MouseBehavior",free.mouseBehavior)
        put(UserInputService,"MouseIconEnabled",free.mouseIcon)
        free=nil
    end
    function API.StopAll()
        stopFreeCam();stopFly();stopNoClip();stopSpeed();nextJump=0
    end
    function API.BlocksCombat() return Native.IsRunning() and S.FreeCam_Enabled end
    function API.Active(name)
        if not Native.IsRunning() then return false end
        if name=="FreeCam" then return free~=nil
        elseif name=="Fly" then return fly~=nil
        elseif name=="NoClip" then return noclip~=nil
        elseif name=="Speed" then return speed~=nil
        elseif name=="InfiniteJump" then
            if not S.InfiniteJump_Enabled then return false end
            local _,humanoid=characterParts()
            return S.InfiniteJump_Enabled and humanoid~=nil and not free and not fly
        end
        return false
    end
    function API.SetGuard(callback) captureGuard=callback end
    function API.Build(window,wrap)
        local specs={
            {id="FreeCam",title="FreeCam",speed="FreeCam_Speed",slider="FreeCam Speed",range={5,500},step=5,
                help="Отдельная камера: персонаж остаётся на месте. WASD — движение, мышь — обзор, Space/E — вверх, Ctrl/Q — вниз, Shift — скорость x2. K открывает меню. При выключении камера и персонаж восстанавливаются. FreeCam и Fly включаются по отдельности."},
            {id="NoClip",title="NoClip",help="Отключает столкновения частей персонажа. Можно проходить через стены и совмещать с Fly. При выключении возвращает исходные столкновения."},
            {id="InfiniteJump",title="Infinite Jump",help="Удерживай Space: персонаж будет повторно получать импульс прыжка и подниматься. Отпусти Space, чтобы остановить подъём. Во время FreeCam и Fly прыжки приостанавливаются."},
            {id="Fly",title="Fly",speed="Fly_Speed",slider="Fly Speed",range={5,300},step=5,
                help="Полёт персонажа: WASD — движение относительно камеры, Space/E — вверх, Ctrl/Q — вниз. Скорость задаётся ползунком. FreeCam выключается при включении Fly."},
            {id="Speed",title="Speed",speed="Speed_Value",slider="Walk Speed",range={1,200},step=1,
                help="Изменяет скорость ходьбы персонажа. При выключении возвращает прежнюю скорость. Для скорости Fly и FreeCam используй их собственные ползунки."},
        }
        for _,spec in ipairs(specs) do
            local id=spec.id
            local tab=wrap(window:CreateTab(spec.title))
            HUDToggleHandles[id]=tab:CreateToggle({Name=spec.title.." Enabled",CurrentValue=false,
                Callback=function(value) API.Toggle(id,value) end})
            if spec.speed then
                local field=spec.speed
                tab:CreateSlider({Name=spec.slider,Range=spec.range,Increment=spec.step,CurrentValue=S[field],
                    Callback=function(value) S[field]=value end})
            end
            tab:CreateParagraph({Title=spec.title,Content=spec.help})
        end
    end
    function API.Toggle(name,enabled)
        S[name.."_Enabled"]=enabled==true
        if enabled and (name=="FreeCam" or name=="Fly") then
            local other=name=="FreeCam" and "Fly" or "FreeCam"
            local handle=HUDToggleHandles[other]
            if S[other.."_Enabled"] and handle then handle:Set(false) end
        end
        if not enabled then
            if name=="FreeCam" then stopFreeCam()
            elseif name=="Fly" then stopFly()
            elseif name=="NoClip" then stopNoClip()
            elseif name=="Speed" then stopSpeed() end
        end
    end
    local function fail(name,err)
        API.Toggle(name,false)
        local handle=HUDToggleHandles[name]
        if handle then handle:Set(false) end
        local message=name..": "..tostring(err)
        if message~=lastError then
            lastError=message;warn("Movement: "..message)
            Rayfield:Notify({Title="Movement",Content=message,Duration=7})
        end
    end
    local function renderFreeCam(dt)
        if not free then return end
        if not Native.IsRunning() or not S.FreeCam_Enabled or ConfigLoading then stopFreeCam();return end
        local allowed=acceptsInput()
        free.camera.CameraType=Enum.CameraType.Scriptable
        free.root.Anchored=true
        local desired=allowed and direction(free.camera)*S.FreeCam_Speed or zero
        if allowed and UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then desired=desired*2 end
        if allowed then
            free.velocity=free.velocity:Lerp(desired,1-math.exp(-12*math.min(dt or 1/60,.1)))
            free.position=free.position+free.velocity*math.min(dt or 1/60,.1)
            UserInputService.MouseBehavior=Enum.MouseBehavior.LockCenter
            UserInputService.MouseIconEnabled=false
        else
            free.velocity=zero
            UserInputService.MouseBehavior=Enum.MouseBehavior.Default
            UserInputService.MouseIconEnabled=true
        end
        free.camera.CFrame=CFrame.new(free.position)*CFrame.fromOrientation(free.pitch,free.yaw,0)
        free.camera.Focus=free.camera.CFrame*CFrame.new(0,0,-512)
    end
    local function startFreeCam(humanoid,root)
        local camera=workspace.CurrentCamera
        if not camera then return end
        local pitch,yaw=camera.CFrame:ToEulerAnglesYXZ()
        free={camera=camera,root=root,humanoid=humanoid,cameraType=camera.CameraType,
            cameraCFrame=camera.CFrame,cameraFocus=camera.Focus,subject=camera.CameraSubject,
            mouseBehavior=UserInputService.MouseBehavior,mouseIcon=UserInputService.MouseIconEnabled,
            anchored=root.Anchored,autoRotate=humanoid.AutoRotate,position=camera.CFrame.Position,
            pitch=pitch,yaw=yaw,velocity=zero}
        root.Anchored=true;humanoid.AutoRotate=false
        camera.CameraType=Enum.CameraType.Scriptable
        local function step(dt)
            local ok,err=pcall(renderFreeCam,dt)
            if not ok then fail("FreeCam",err) end
        end
        local ok=pcall(function() RunService:BindToRenderStep(renderName,Enum.RenderPriority.Camera.Value+1,step) end)
        if ok then renderBound=true else renderFallback=RunService.RenderStepped:Connect(step) end
    end
    local function startFly(humanoid,root)
        fly={root=root,humanoid=humanoid,autoRotate=humanoid.AutoRotate,platformStand=humanoid.PlatformStand,objects={}}
        local function object(class)
            local item=Instance.new(class);table.insert(fly.objects,item);item.Name="DEV_HUB_"..class;item.Parent=root
            return item
        end
        local attachment=object("Attachment")
        local velocity=object("LinearVelocity")
        velocity.Attachment0=attachment;velocity.RelativeTo=Enum.ActuatorRelativeTo.World
        velocity.VelocityConstraintMode=Enum.VelocityConstraintMode.Vector
        velocity.ForceLimitsEnabled=false;velocity.MaxForce=math.huge;velocity.VectorVelocity=zero
        local orientation=object("AlignOrientation")
        orientation.Mode=Enum.OrientationAlignmentMode.OneAttachment;orientation.Attachment0=attachment
        orientation.MaxTorque=math.huge;orientation.Responsiveness=25
        fly.velocity=velocity;fly.orientation=orientation
        humanoid.AutoRotate=false;humanoid.PlatformStand=true
    end
    local function startNoClip(character)
        noclip={character=character,parts={}}
        local owner=noclip
        local function track(part)
            if part:IsA("BasePart") and owner.parts[part]==nil then
                owner.parts[part]=part.CanCollide;part.CanCollide=false
            end
        end
        local queue={character}
        local visited,head=0,1
        while head<=#queue and visited<256 do
            local object=queue[head];queue[head]=false;head=head+1;visited=visited+1;track(object)
            for _,child in ipairs(object:GetChildren()) do
                track(child)
                if #queue<256 then table.insert(queue,child) end
            end
        end
        owner.added=character.DescendantAdded:Connect(function(part)
            if noclip==owner then local ok,err=pcall(track,part);if not ok then fail("NoClip",err) end end
        end)
    end
    local function physicsStep()
        if not Native.IsRunning() or ConfigLoading then API.StopAll();return end
        local character,humanoid,root=characterParts()
        if currentCharacter~=character then API.StopAll();currentCharacter=character end
        if not humanoid or not root then API.StopAll();return end
        if S.FreeCam_Enabled then
            stopFly()
            if free and (free.root~=root or free.humanoid~=humanoid or free.camera~=workspace.CurrentCamera) then stopFreeCam() end
            if not free then local ok,err=pcall(startFreeCam,humanoid,root);if not ok then fail("FreeCam",err) end end
        else stopFreeCam() end
        if S.Fly_Enabled and not S.FreeCam_Enabled then
            local ok,err=pcall(function()
                if fly and (fly.root~=root or fly.humanoid~=humanoid) then stopFly() end
                if not fly then startFly(humanoid,root) end
                fly.velocity.VectorVelocity=direction(workspace.CurrentCamera)*S.Fly_Speed
                local camera=workspace.CurrentCamera
                if camera then
                    local look=camera.CFrame.LookVector
                    local horizontal=Vector3.new(look.X,0,look.Z)
                    if horizontal.Magnitude>.001 then fly.orientation.CFrame=CFrame.lookAt(zero,horizontal) end
                end
                humanoid.PlatformStand=true;humanoid.AutoRotate=false
            end)
            if not ok then fail("Fly",err) end
        else stopFly() end
        if S.NoClip_Enabled then
            local ok,err=pcall(function()
                if noclip and noclip.character~=character then stopNoClip() end
                if not noclip then startNoClip(character) end
                for part in pairs(noclip.parts) do
                    if part.Parent and part:IsDescendantOf(character) then part.CanCollide=false
                    else put(part,"CanCollide",noclip.parts[part]);noclip.parts[part]=nil end
                end
            end)
            if not ok then fail("NoClip",err) end
        else stopNoClip() end
        if S.Speed_Enabled then
            local ok,err=pcall(function()
                if speed and speed.humanoid~=humanoid then stopSpeed() end
                if not speed then speed={humanoid=humanoid,original=humanoid.WalkSpeed} end
                if humanoid.WalkSpeed~=S.Speed_Value then humanoid.WalkSpeed=S.Speed_Value end
            end)
            if not ok then fail("Speed",err) end
        else stopSpeed() end
        if S.InfiniteJump_Enabled and not free and not fly and acceptsInput() and UserInputService:IsKeyDown(Enum.KeyCode.Space) then
            local now=os.clock()
            if now>=nextJump then
                nextJump=now+.12
                local ok,err=pcall(function()
                    local power=humanoid.UseJumpPower and humanoid.JumpPower
                        or math.sqrt(2*workspace.Gravity*humanoid.JumpHeight)
                    local velocity=root.AssemblyLinearVelocity
                    humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                    root.AssemblyLinearVelocity=Vector3.new(velocity.X,math.max(45,power),velocity.Z)
                end)
                if not ok then fail("InfiniteJump",err) end
            end
        else nextJump=0 end
    end
    function API.Init()
        Native.Connect(RunService.PreSimulation,function()
            local ok,err=pcall(physicsStep)
            if not ok then API.StopAll();warn("Movement: "..tostring(err)) end
        end)
        Native.Connect(UserInputService.InputChanged,function(input)
            if free and input.UserInputType==Enum.UserInputType.MouseMovement and acceptsInput() then
                free.yaw=free.yaw-input.Delta.X*.0025
                free.pitch=math.max(-math.rad(89),math.min(math.rad(89),free.pitch-input.Delta.Y*.0025))
            end
        end)
        Native.Connect(UserInputService.WindowFocusReleased,function() focused=false end)
        Native.Connect(UserInputService.WindowFocused,function() focused=true end)
        Native.Connect(LocalPlayer.CharacterRemoving,function() API.StopAll();currentCharacter=nil end)
    end
    function API.Debug() return {free=free,fly=fly,speed=speed,noclip=noclip} end
    return API
end)()


-- Caches unificate e ottimizzate
local ESP_Cache = {}
local NativeESPDrawCount=0
local NativeESPNextFrame=0
local NativeESPDeadline=0
local NativeESPEpoch=0
local Visibility_Cache = {}
local Tracked_NPCs = {}
 
-- Raycast ottimizzato (Creato una sola volta e riutilizzato)
local rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude
 
local function refreshRayFilter()
    local list = {}
    local char = LocalPlayer.Character
    local cam = workspace.CurrentCamera
    if char then table.insert(list, char) end
    if cam then table.insert(list, cam) end
    rayParams.FilterDescendantsInstances = list
end
 
-- FOV drawing is created only after the user enables its display.
local FOVCircle
local function UpdateAimbotFOV(mousePos)
    if not S.Show_FOV then
        if FOVCircle then FOVCircle.Visible=false end
        return
    end
    if not FOVCircle then
        local ok,result=pcall(function() return Native.Visuals.new("Circle") end)
        if not ok then
            S.Show_FOV=false
            if HUDToggleHandles.AimFOV then HUDToggleHandles.AimFOV:Set(false) end
            Rayfield:Notify({Title="FOV display unavailable",Content=tostring(result),Duration=6})
            return
        end
        FOVCircle=result
        FOVCircle.Thickness=1
        FOVCircle.Color=Color3.fromRGB(255,255,255)
        FOVCircle.Transparency=1
        FOVCircle.Filled=false
    end
    FOVCircle.Position=mousePos
    FOVCircle.Radius=S.Aim_FOV
    FOVCircle.Visible=true
end

-- ==========================================
-- GESTIONE MEMORIA E CLEANUP
-- ==========================================
local function ClearEntityESP(id)
    if ESP_Cache[id] then
        ESP_Cache[id].Box:Remove()
        ESP_Cache[id].Text:Remove()
        ESP_Cache[id].Tracer:Remove()
        ESP_Cache[id] = nil
    end
    Visibility_Cache[id] = nil
end
 
local function HideESP(id)
    local cached = ESP_Cache[id]
    if not cached then return end
    cached.Box.Visible = false
    cached.Text.Visible = false
    cached.Tracer.Visible = false
end
 
Native.Connect(Players.PlayerRemoving,function(player)
    ClearEntityESP(tostring(player.UserId))
end)
 
-- ==========================================
-- UNIVERSAL NPC SCANNER
-- ==========================================
local function IsNPC(model)
    local hum = model:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return false end
    if not model:FindFirstChild("HumanoidRootPart") then return false end
    if Players:GetPlayerFromCharacter(model) then return false end
    return true
end
 
local function CheckAndAddNPC(obj)
    if IsNPC(obj) then Tracked_NPCs[obj] = true end
end
 
local function RemoveNPC(obj)
    if Tracked_NPCs[obj] then
        Tracked_NPCs[obj] = nil
        ClearEntityESP(obj)
    end
end
 
-- Incremental discovery: no whole-map GetDescendants(), no task per added object.
local NPCScanStartedAt=os.clock()
local NPCScanState={stack={},nextAt=0,running=false,completed=false,restart=false,examined=0}
local NPCPending,NPCPendingSet={},{}
local NPCPendingHead,NPCPendingTail=1,0
local NPCScanStatusLabel
local NPCScanLastStatusAt=-math.huge

local function NPCFeaturesNeeded()
    return Native.IsRunning() and not ConfigLoading and S.NPCScan_Enabled and (S.NPC_ESP_Enabled or S.NPC_Tracers_Enabled
        or (S.Aimbot_Enabled and S.Aimbot_Target_NPCs)
        or (S.Assist_Enabled and S.Assist_Target_NPCs))
end

local function ClearNPCPending()
    NPCPending,NPCPendingSet={},{}
    NPCPendingHead,NPCPendingTail=1,0
end

local function StartNPCTraversal()
    NPCScanState.stack={{node=workspace}}
    NPCScanState.completed=false
    NPCScanState.restart=false
    NPCScanState.examined=0
end

local function NPCScanStatus(text)
    if os.clock()-NPCScanLastStatusAt<0.5 then return end
    NPCScanLastStatusAt=os.clock()
    if NPCScanStatusLabel then NPCScanStatusLabel:Set("NPC Scanner: "..text) end
end

local function QueueNPCCheck(model)
    if not NPCFeaturesNeeded() or not model or not model:IsA("Model") or NPCPendingSet[model] then return end
    if NPCPendingTail-NPCPendingHead+1>=1024 then
        NPCScanState.rescanAfterComplete=true
        return
    end
    NPCPendingTail=NPCPendingTail+1
    NPCPending[NPCPendingTail]=model
    NPCPendingSet[model]=true
end

Native.Connect(workspace.DescendantAdded,function(obj)
    if not NPCFeaturesNeeded() then return end
    if obj:IsA("Humanoid") or obj.Name=="HumanoidRootPart" then QueueNPCCheck(obj.Parent) end
end)
Native.Connect(workspace.DescendantRemoving,RemoveNPC)

local function UpdateNPCScanner()
    local state=NPCScanState
    local now=os.clock()
    if not NPCFeaturesNeeded() then
        if state.running then
            state.stack={}
            ClearNPCPending()
            state.running=false
        end
        NPCScanStatus(S.NPCScan_Enabled and "idle — enable an NPC feature" or "disabled")
        return
    end
    if not state.running then
        state.running=true
        StartNPCTraversal()
        state.nextAt=now
    end
    local readyAt=NPCScanStartedAt+S.NPCScan_StartupDelay
    if now<readyAt then
        NPCScanStatus(string.format("starting in %.1fs",readyAt-now))
        return
    end
    if now<state.nextAt then return end
    state.nextAt=now+math.max(50,S.NPCScan_IntervalMs)/1000
    if state.restart or (state.completed and state.rescanAfterComplete) then
        state.rescanAfterComplete=false
        StartNPCTraversal()
    end
    local deadline=now+0.0015
    local budget=math.max(1,math.floor(S.NPCScan_Batch))
    local processed,operations=0,0
    -- Reserve most of each batch for traversal so an event burst cannot starve discovery.
    local pendingBudget=math.min(5,math.max(1,math.floor(budget/4)))
    while processed<pendingBudget and NPCPendingHead<=NPCPendingTail and os.clock()<deadline do
        local model=NPCPending[NPCPendingHead]
        NPCPending[NPCPendingHead]=nil
        NPCPendingHead=NPCPendingHead+1
        NPCPendingSet[model]=nil
        if model:IsDescendantOf(workspace) then CheckAndAddNPC(model) end
        processed=processed+1
    end
    if NPCPendingHead>NPCPendingTail then ClearNPCPending() end
    -- Expand one child at a time: even a wide folder never queues all its children in a loop.
    while processed<budget and operations<budget*4 and #state.stack>0 and os.clock()<deadline do
        operations=operations+1
        local frame=state.stack[#state.stack]
        local node=frame.node
        if node~=workspace and not node:IsDescendantOf(workspace) then
            state.stack[#state.stack]=nil
        elseif not frame.children then
            if node:IsA("Model") then CheckAndAddNPC(node) end
            frame.children=node:GetChildren()
            frame.index=1
            processed=processed+1
            state.examined=state.examined+1
        else
            local child=frame.children[frame.index]
            if child then
                frame.index=frame.index+1
                state.stack[#state.stack+1]={node=child}
            else
                state.stack[#state.stack]=nil
            end
        end
    end
    state.completed=#state.stack==0
    local found=0
    for _ in pairs(Tracked_NPCs) do found=found+1 end
    NPCScanStatus(string.format("%s | checked %d | NPCs %d",
        state.completed and "watching" or "scanning",state.examined,found))
end

 
-- ==========================================
-- SMART MULTI-POINT WALL CHECK
-- ==========================================
local function GetVisibility(targetId, char)
    local currentTime = tick()
 
    if Visibility_Cache[targetId] and (currentTime - Visibility_Cache[targetId].lastUpdate) < 0.1 then
        return Visibility_Cache[targetId].isVisible
    end
 
    local cam = workspace.CurrentCamera
    if not cam then return false end
 
    -- Controlla 6 punti estremi per il CQC (Close Quarters Combat)
    local partsToCheck = {
        char:FindFirstChild("Head"),
        char:FindFirstChild("HumanoidRootPart"),
        char:FindFirstChild("Right Arm") or char:FindFirstChild("RightUpperArm"),
        char:FindFirstChild("Left Arm") or char:FindFirstChild("LeftUpperArm"),
        char:FindFirstChild("Right Leg") or char:FindFirstChild("RightUpperLeg"),
        char:FindFirstChild("Left Leg") or char:FindFirstChild("LeftUpperLeg")
    }
 
    local origin = cam.CFrame.Position
    local isVisible = false
    
    for _, part in pairs(partsToCheck) do
        if part and part:IsA("BasePart") then
            local result = workspace:Raycast(origin, part.Position - origin, rayParams)
            if result and result.Instance:IsDescendantOf(char) then
                isVisible = true
                break
            end
        end
    end
 
    Visibility_Cache[targetId] = { isVisible = isVisible, lastUpdate = currentTime }
    return isVisible
end
 
-- Manual UserId exclusions. ESP visibility/colors never decide friendship.
local Friends=(function()
    local API={OnChanged=function() end}
    local ids={}
    local lastPlayer
    local card,title,details
    local nextUpdate=0
    local input,dropdown,listLabel,lastLabel
    local selected
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    params.IgnoreWater=true

    local function key(value)
        if type(value)~="string" and type(value)~="number" then return nil end
        local text=tostring(value):match("^%s*(%d+)%s*$")
        local number=text and tonumber(text)
        if not number or number<1 or number>9007199254740991 or number~=math.floor(number) then return nil end
        return string.format("%.0f",number)
    end
    -- RIVALS uses TeamID/EnvironmentID independently of Roblox Player.Team.
    -- Compare the complete values, including invisible bytes. Empty/missing IDs are unknown.
    local function teamToken(player,attribute)
        local ok,value=pcall(function() return player:GetAttribute(attribute) end)
        if not ok then return nil end
        if type(value)=="number" and value==value and value~=math.huge and value~=-math.huge then
            return "number:"..tostring(value)
        end
        if type(value)=="string" and #value>0 then return "string:"..value end
        return nil
    end
    local function byteText(player,attribute)
        local ok,value=pcall(function() return player:GetAttribute(attribute) end)
        if not ok or value==nil then return "missing" end
        if type(value)~="string" then return tostring(value) end
        if #value==0 then return "empty string" end
        local bytes={}
        for i=1,math.min(8,#value) do bytes[i]=string.format("%02X",string.byte(value,i)) end
        return table.concat(bytes," ")..(#value>8 and "..." or "")
    end
    function API.TeamStatus(player)
        if not player or player==LocalPlayer then return "Self" end
        if game.GameId==6035872082 then
            local ownTeam,otherTeam=teamToken(LocalPlayer,"TeamID"),teamToken(player,"TeamID")
            local ownMatch,otherMatch=teamToken(LocalPlayer,"EnvironmentID"),teamToken(player,"EnvironmentID")
            if not ownTeam or not otherTeam or not ownMatch or not otherMatch then return "Unknown" end
            if ownMatch~=otherMatch then return "Other match" end
            return ownTeam==otherTeam and "Ally" or "Enemy"
        end
        if LocalPlayer.Team~=nil and player.Team~=nil and LocalPlayer.Neutral==false and player.Neutral==false then
            return LocalPlayer.Team==player.Team and "Ally" or "Enemy"
        end
        return "Unknown"
    end
    function API.TeamBytes(player)
        return "TeamID bytes: "..byteText(player,"TeamID").." | EnvironmentID: "..byteText(player,"EnvironmentID")
    end
    local teamLabel,nextTeamLabel=nil,0

    local function notify(message)
        Rayfield:Notify({Title="FriendNoTrigger",Content=message,Duration=4})
    end
    local function make(class,properties,parent)
        local instance=Instance.new(class)
        for name,value in pairs(properties) do instance[name]=value end
        DeltaLanguage.Track(instance)
        instance.Parent=parent
        return instance
    end
    function API.Hide()
        if card then card.Visible=false end
    end
    local function show(player)
        if not card then
            card=make("Frame",{Name="TargetInfo",Size=UDim2.new(0,330,0,66),
                Position=UDim2.new(.5,-165,1,-100),BackgroundColor3=Color3.fromRGB(8,24,35),
                BackgroundTransparency=.08,BorderSizePixel=0,Visible=false},Native.Window())
            make("UICorner",{CornerRadius=UDim.new(0,10)},card)
            make("UIStroke",{Color=Color3.fromRGB(35,117,150),Transparency=.35,Thickness=1},card)
            title=make("TextLabel",{BackgroundTransparency=1,Position=UDim2.new(0,12,0,8),
                Size=UDim2.new(1,-24,0,23),Font=Enum.Font.GothamSemibold,TextSize=12,
                TextColor3=Color3.fromRGB(120,213,246),TextXAlignment=Enum.TextXAlignment.Left,Text=""},card)
            details=make("TextLabel",{BackgroundTransparency=1,Position=UDim2.new(0,12,0,32),
                Size=UDim2.new(1,-24,0,22),Font=Enum.Font.Gotham,TextSize=11,
                TextColor3=Color3.fromRGB(94,180,218),TextXAlignment=Enum.TextXAlignment.Left,Text=""},card)
        end
        local id=key(player.UserId)
        local name=(player.DisplayName or player.Name).." (@"..player.Name..")"
        local relation=API.TeamStatus(player)
        local protected=ids[id] or (S.FriendNoTrigger_Teammates and relation=="Ally")
        local state=protected and (S.FriendNoTrigger and "Ignored: "..relation or relation.." / filter OFF") or relation
        local text="UserId: "..id.."  |  "..state
        if title.Text~=name then title.Text=name end
        if details.Text~=text then details.Text=text end
        card.Visible=true
    end
    function API.Contains(character)
        if not S.FriendNoTrigger or not character then return false end
        local player=Players:GetPlayerFromCharacter(character)
        if not player or player==LocalPlayer then return false end
        return ids[key(player.UserId)]==true or (S.FriendNoTrigger_Teammates and API.TeamStatus(player)=="Ally")
    end
    function API.Export()
        local copy={}
        for id in pairs(ids) do copy[id]=true end
        return copy
    end
    function API.Validate(data)
        assert(data==nil or type(data)=="table","Invalid friend list")
        local result,count={},0
        for id,enabled in pairs(data or {}) do
            assert(type(id)=="string" and key(id)==id and enabled==true,"Invalid friend UserId")
            count=count+1;assert(count<=256,"Friend list limit is 256")
            result[id]=true
        end
        return result
    end
    function API.Refresh()
        if not dropdown then return end
        local names={}
        for _,player in ipairs(Players:GetPlayers()) do names[key(player.UserId) or ""]=player.Name end
        local ordered={}
        for id in pairs(ids) do table.insert(ordered,id) end
        table.sort(ordered,function(a,b) return tonumber(a)<tonumber(b) end)
        local options,choice={},nil
        for _,id in ipairs(ordered) do
            local text=id..(names[id] and " (@"..names[id]..")" or "")
            table.insert(options,text)
            if id==selected then choice=text end
        end
        dropdown:Refresh(options)
        dropdown:Set(choice and {choice} or {})
        listLabel:Set("Ignored UserIds: "..#ordered.." / 256")
    end
    function API.Replace(data)
        ids=API.Validate(data)
        API.Refresh()
    end
    function API.Add(value)
        local id=key(value)
        if not id then notify("Enter a positive numeric UserId.");return false end
        if id==key(LocalPlayer.UserId) then notify("Choose another player.");return false end
        if not ids[id] then
            local count=0;for _ in pairs(ids) do count=count+1 end
            if count>=256 then notify("Friend list is full (256).");return false end
        end
        ids[id]=true;selected=id
        API.OnChanged();API.Refresh()
        notify("Added UserId "..id..(S.FriendNoTrigger and "." or ". Enable FriendNoTrigger to protect this player."))
        return true
    end
    function API.Remove(value)
        local id=key(value)
        if not id or not ids[id] then notify("Select a UserId from Ignored Players.");return false end
        ids[id]=nil;selected=nil
        API.OnChanged();API.Refresh();notify("Removed UserId "..id..".")
        return true
    end
    function API.Clear()
        ids={};selected=nil;API.OnChanged();API.Refresh()
    end
    function API.Build(tab)
        tab:CreateToggle({Name="Ignore Teammates",CurrentValue=true,Callback=function(value)
            S.FriendNoTrigger_Teammates=value;API.OnChanged()
        end})
        teamLabel=tab:CreateLabel(API.TeamBytes(LocalPlayer))
        tab:CreateParagraph({Title="Проверка команд RIVALS",
            Content="FriendNoTrigger + Ignore Teammates пропускает союзников. Для RIVALS сравнивает TeamID внутри одного EnvironmentID, включая невидимые символы. Сверху показаны реальные байты ID. Пустые и отсутствующие значения дают Unknown; одинаковые nil не считаются командой. В других играх используются непустые Roblox Team при Neutral=false. Ручной список UserId тоже работает."})
        tab:CreateToggle({Name="Show Target ID",CurrentValue=true,Callback=function(value)
            S.TargetInfo_Enabled=value
            if not value then API.Hide() end
        end})
        lastLabel=tab:CreateLabel("Last target: none — hide the menu and point at a player")
        input=tab:CreateInput({Name="Player UserId",CurrentValue="",PlaceholderText="Numeric Roblox UserId",Callback=function() end})
        tab:CreateButton({Name="Use Last Target ID",Callback=function()
            if not lastPlayer then notify("Enable Show Target ID, hide the menu, and point at a player first.");return end
            input:Set(key(lastPlayer.UserId))
        end})
        tab:CreateButton({Name="Add Last Target",Callback=function()
            if not lastPlayer then notify("Point at a player with Show Target ID enabled first.");return end
            input:Set(key(lastPlayer.UserId));API.Add(lastPlayer.UserId)
        end})
        tab:CreateButton({Name="Add UserId",Callback=function() API.Add(input.CurrentValue) end})
        dropdown=tab:CreateDropdown({Name="Ignored Players",Options={},CurrentOption={},Callback=function(value)
            selected=value[1] and key(value[1]:match("^(%d+)")) or nil
        end})
        tab:CreateButton({Name="Remove Selected UserId",Callback=function() API.Remove(selected) end})
        tab:CreateButton({Name="Clear Friend List",Callback=function() API.Clear() end})
        listLabel=tab:CreateLabel("Ignored UserIds: 0 / 256")
        tab:CreateParagraph({Title="Исключения по UserId",
            Content="Включи Show Target ID, закрой меню на K и наведи курсор на игрока: появятся его имя и UserId. Открой меню и нажми Add Last Target либо введи ID вручную и нажми Add UserId. При включённом FriendNoTrigger список исключается из Aimbot, Aim Assist и Triggerbot. Цвет ESP не учитывается. Список сохраняется в Config. У NPC нет UserId."})
        API.Refresh()
    end
    function API.Update(active)
        if teamLabel and os.clock()>=nextTeamLabel then
            nextTeamLabel=os.clock()+.5
            local text=API.TeamBytes(LocalPlayer)
            if teamLabel.CurrentValue~=text then teamLabel:Set(text) end
        end
        if not active or not S.TargetInfo_Enabled or Native.MenuFrame().Visible
            or Native.SystemMenuOpen() or UserInputService:GetFocusedTextBox() then API.Hide();return end
        local now=os.clock()
        if now<nextUpdate then return end
        nextUpdate=now+.1
        local camera=workspace.CurrentCamera
        if not camera then API.Hide();return end
        local ray
        if UserInputService.MouseBehavior==Enum.MouseBehavior.LockCenter then
            local center=camera.ViewportSize/2
            ray=camera:ViewportPointToRay(center.X,center.Y)
        else
            local cursor=UserInputService:GetMouseLocation()
            ray=camera:ScreenPointToRay(cursor.X,cursor.Y)
        end
        local ignored={camera}
        if LocalPlayer.Character then table.insert(ignored,LocalPlayer.Character) end
        params.FilterDescendantsInstances=ignored
        local hit=workspace:Raycast(ray.Origin,ray.Direction*10000,params)
        local ancestor=hit and hit.Instance
        for _=1,12 do
            if not ancestor or ancestor==workspace then break end
            if ancestor:IsA("Model") then
                local player=Players:GetPlayerFromCharacter(ancestor)
                if player and player~=LocalPlayer and key(player.UserId) then
                    if lastPlayer~=player and lastLabel then lastLabel:Set("Last target: @"..player.Name.." / UserId: "..key(player.UserId)) end
                    lastPlayer=player;show(player);return
                end
            end
            ancestor=ancestor.Parent
        end
        API.Hide()
    end
    function API.Card() return card end
    function API.LastPlayer() return lastPlayer end
    return API
end)()

local function IsFriendNoTriggerCharacter(character)
    return Friends.Contains(character)
end


-- ==========================================
-- ESP ENGINE UNIFICATO E OTTIMIZZATO
-- ==========================================
local function DrawESP(id, char, hrp, name, team, isNPC)
    local showBox = isNPC and S.NPC_ESP_Enabled or (not isNPC and S.ESP_Enabled)
    local showTracer = isNPC and S.NPC_Tracers_Enabled or (not isNPC and S.Tracers_Enabled)
    local maxDist = isNPC and S.NPC_ESP_MaxDistance or S.ESP_MaxDistance
 
    if not showBox and not showTracer then return end -- Il loop principale gestisce già HideESP
 
    local cam = workspace.CurrentCamera
    if not cam then return end
 
    local dist = (cam.CFrame.Position - hrp.Position).Magnitude
    if dist > maxDist or dist == 0 then return end
 
    local rootScreen, onScreen = cam:WorldToViewportPoint(hrp.Position)
    if not onScreen then return end
 
    if NativeESPDrawCount>=S.ESP_MaxVisible or os.clock()>NativeESPDeadline then return end
    NativeESPDrawCount=NativeESPDrawCount+1
    -- Native GUI objects are only created for entities that will be displayed.
    if not ESP_Cache[id] then
        ESP_Cache[id] = { Box = Native.Visuals.new("Square"), Text = Native.Visuals.new("Text"), Tracer = Native.Visuals.new("Line") }
        ESP_Cache[id].Box.Thickness = 1.5; ESP_Cache[id].Box.Filled = false
        ESP_Cache[id].Text.Size = 14; ESP_Cache[id].Text.Center = true; ESP_Cache[id].Text.Outline = true
        ESP_Cache[id].Tracer.Thickness = 1.5
    end
 
    ESP_Cache[id].lastRendered=os.clock()
    ESP_Cache[id].epoch=NativeESPEpoch
    ESP_Cache[id].character=char
    ESP_Cache[id].root=hrp
    ESP_Cache[id].humanoid=char:FindFirstChildOfClass("Humanoid")
    ESP_Cache[id].isNPC=isNPC
    local box, text, tracer = ESP_Cache[id].Box, ESP_Cache[id].Text, ESP_Cache[id].Tracer
 
    local topScreenPos = cam:WorldToViewportPoint(hrp.Position + ESP_CONFIG.TOP_OFFSET)
    local bottomScreenPos = cam:WorldToViewportPoint(hrp.Position - ESP_CONFIG.BOTTOM_OFFSET)
 
    local height = math.abs(bottomScreenPos.Y - topScreenPos.Y)
    local width = height / 2
    if height < ESP_CONFIG.MIN_HEIGHT then
        height = ESP_CONFIG.MIN_HEIGHT; width = ESP_CONFIG.MIN_WIDTH
    end
 
    local visible = GetVisibility(id, char)
    local isTeammate=not isNPC and Friends.TeamStatus(Players:GetPlayerFromCharacter(char))=="Ally"
    local renderColor
 
    if isNPC then
        -- NPCs: cyan when visible, magenta behind cover.
        renderColor = visible and Color3.fromRGB(0, 200, 255) or Color3.fromRGB(200, 0, 255)
    elseif isTeammate then
        -- The same team resolver as FriendNoTrigger; coloring works independently of its toggles.
        renderColor = Color3.fromRGB(175, 90, 255)
    else
        renderColor = visible and Color3.new(0, 1, 0) or Color3.new(1, 0, 0)
    end
 
    ESP_Cache[id].green=not isNPC and visible and not isTeammate
    if showBox then
        box.Size = Vector2.new(width, height)
        box.Position = Vector2.new(rootScreen.X - (width / 2), topScreenPos.Y)
        box.Color = renderColor
        box.Visible = true
 
        local prefix = isNPC and "[NPC] " or ""
        text.Text = string.format("%s%s [%dm]", prefix, name, math.floor(dist / ESP_CONFIG.DISTANCE_DIVISOR))
        text.Position = Vector2.new(rootScreen.X, topScreenPos.Y - 18)
        text.Color = renderColor
        text.Visible = true
    end
 
    if showTracer then
        tracer.From = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y)
        tracer.To = Vector2.new(rootScreen.X, bottomScreenPos.Y)
        tracer.Color = renderColor
        tracer.Visible = true
    end
end
 
-- Track only the selected visible entities every render frame.
-- No raycasts, map enumeration or nearest-target searches in this pass.
local function ProjectCachedESP()
    if not Native.IsRunning() then return end
    local camera=workspace.CurrentCamera
    if not camera then return end
    for id,cached in pairs(ESP_Cache) do
        if cached.epoch==NativeESPEpoch then
            local boxOn=cached.isNPC and S.NPC_ESP_Enabled or (not cached.isNPC and S.ESP_Enabled)
            local tracerOn=cached.isNPC and S.NPC_Tracers_Enabled or (not cached.isNPC and S.Tracers_Enabled)
            local root,humanoid=cached.root,cached.humanoid
            local valid=(boxOn or tracerOn) and root and root.Parent and humanoid and humanoid.Health>0
            if valid then
                local distance=(camera.CFrame.Position-root.Position).Magnitude
                local limit=cached.isNPC and S.NPC_ESP_MaxDistance or S.ESP_MaxDistance
                local screen,onScreen=camera:WorldToViewportPoint(root.Position)
                if distance>limit or distance==0 or not onScreen then
                    HideESP(id)
                else
                    local top=camera:WorldToViewportPoint(root.Position+ESP_CONFIG.TOP_OFFSET)
                    local bottom=camera:WorldToViewportPoint(root.Position-ESP_CONFIG.BOTTOM_OFFSET)
                    local height=math.abs(bottom.Y-top.Y)
                    local width=height/2
                    if height<ESP_CONFIG.MIN_HEIGHT then height=ESP_CONFIG.MIN_HEIGHT;width=ESP_CONFIG.MIN_WIDTH end
                    if boxOn then
                        cached.Box.Size=Vector2.new(width,height)
                        cached.Box.Position=Vector2.new(screen.X-width/2,top.Y)
                        cached.Text.Position=Vector2.new(screen.X,top.Y-18)
                    end
                    cached.Box.Visible=boxOn;cached.Text.Visible=boxOn
                    if tracerOn then
                        cached.Tracer.From=Vector2.new(camera.ViewportSize.X/2,camera.ViewportSize.Y)
                        cached.Tracer.To=Vector2.new(screen.X,bottom.Y)
                    end
                    cached.Tracer.Visible=tracerOn
                end
            else HideESP(id) end
        end
    end
end

-- ==========================================
-- CONFIGURABLE AIMBOT INPUT
-- ==========================================
local AimHeld = false
local AimToggled = false
local AimCapturingBind = false
local AimCaptureStarted = 0
local AimWindowFocused = true
local AimBindLabel

local function ResetAimActivation()
    AimHeld, AimToggled = false, false
    CurrentAimPart, CurrentAimCamera = nil, nil
    CurrentAimUpdate = -math.huge
end

local function GetAimPosition(part, camera)
    local position = part.Position
    if S.Prediction_Enabled then
        local distance = (position - camera.CFrame.Position).Magnitude
        local speed = math.max(S.Bullet_Speed, MIN_BULLET_SPEED)
        position = position + part.AssemblyLinearVelocity * (distance / speed)
    end
    return position
end

local function IsSyntheticMouseInput(input)
    return input.UserInputType == SyntheticMouseButton and os.clock() <= SyntheticMouseUntil
end

local function UpdateAimBindLabel()
    Native.RefreshBinds()
    if AimBindLabel then
        AimBindLabel:Set(AimCapturingBind
            and "Press a key or mouse button (Esc to cancel)"
            or ("Aimbot Bind: " .. S.Aimbot_Bind.Name))
    end
end

local function MatchesAimBind(input)
    return input.UserInputType == S.Aimbot_Bind
        or (input.UserInputType == Enum.UserInputType.Keyboard
            and input.KeyCode == S.Aimbot_Bind)
end

local function IsAimbotActive()
    if not Native.IsRunning() or Native.IsInteracting() or Native.SystemMenuOpen() or Movement.BlocksCombat() or ConfigLoading or not S.Aimbot_Enabled or AimCapturingBind or HUDCapture or not AimWindowFocused
        or UserInputService:GetFocusedTextBox() then return false end
    if S.Aimbot_Activation == "Toggle Module" then return true end
    if S.Aimbot_Activation == "Toggle" then return AimToggled end
    return AimHeld
end

Native.Connect(UserInputService.InputBegan,function(input, processed)
    if HUDCapture or IsSyntheticMouseInput(input) then return end
    if AimCapturingBind then
        -- Ignore the UI click that starts rebinding.
        if os.clock() - AimCaptureStarted < 0.2 then return end
        if UserInputService:GetFocusedTextBox() then return end
        if input.KeyCode == Enum.KeyCode.K then
            Rayfield:Notify({Title="Menu key",Content="K opens/closes ClickGUI. Choose another feature key.",Duration=3})
            return
        end
        if input.KeyCode == Enum.KeyCode.Escape then
            AimCapturingBind = false
            UpdateAimBindLabel()
            return
        end
        local newBind
        if input.UserInputType == Enum.UserInputType.Keyboard
            and input.KeyCode ~= Enum.KeyCode.Unknown then
            newBind = input.KeyCode
        elseif input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.MouseButton2
            or input.UserInputType == Enum.UserInputType.MouseButton3 then
            newBind = input.UserInputType
        end
        if newBind then
            S.Aimbot_Bind = newBind
            AimCapturingBind = false
            ResetAimActivation()
            UpdateAimBindLabel()
        end
        return
    end

    if (processed and input.UserInputType~=Enum.UserInputType.Keyboard) or not AimWindowFocused
        or UserInputService:GetFocusedTextBox() then return end
    if Native.SystemMenuOpen() then return end
    if input.UserInputType==Enum.UserInputType.Keyboard and input.KeyCode==Enum.KeyCode.K then return end
    if not MatchesAimBind(input) then return end
    if not S.Aimbot_Enabled then
        if S.Aimbot_Activation~="Toggle" then return end
        HUDToggleHandles.Aimbot:Set(true)
    end
    if not Native.IsRunning() then Native.Start(true) end
    if S.Aimbot_Activation=="Toggle Module" then return end
    if S.Aimbot_Activation == "Toggle" then
        AimToggled = not AimToggled
        Rayfield:Notify({
            Title = "Aimbot",
            Content = AimToggled and "Active" or "Inactive",
            Duration = 2,
        })
    else
        AimHeld = true
    end
end)

Native.Connect(UserInputService.InputEnded,function(input)
    if IsSyntheticMouseInput(input) then return end
    -- Always process releases, including releases over the menu or chat.
    if MatchesAimBind(input) then AimHeld = false end
end)

Native.Connect(UserInputService.WindowFocusReleased,function()
    AimWindowFocused = false
    AimHeld = false
end)
Native.Connect(UserInputService.WindowFocused,function()
    AimWindowFocused = true
end)
Native.Connect(UserInputService.TextBoxFocused,function()
    AimHeld = false
end)
Native.Connect(LocalPlayer.CharacterRemoving,ResetAimActivation)

-- ==========================================
-- HEAD-LOCK AIMBOT TARGET FINDER
-- ==========================================
local function FindClosestAimTargetNow()
    if not S.Aimbot_Enabled then return nil end
 
    local cam = workspace.CurrentCamera
    if not cam then return nil end
 
    local target = nil
    local shortestDistance = S.Aim_FOV
    local mousePos = UserInputService:GetMouseLocation()
 
    local function CheckTarget(entityId, character)
        if IsFriendNoTriggerCharacter(character) then return end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health <= 0 then return end
        local aimPart
        if S.Triggerbot_Enabled and S.Triggerbot_Mode == "With Aimbot"
            and S.Triggerbot_Target == "Body" then
            aimPart = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
                or character:FindFirstChild("LowerTorso") or character:FindFirstChild("HumanoidRootPart")
        else
            aimPart = character:FindFirstChild("Head") or character:FindFirstChild("HumanoidRootPart")
        end
        if not aimPart then return end
 
        local screenPos, onScreen = cam:WorldToViewportPoint(aimPart.Position)
        if onScreen then
            local distanceToMouse = (Vector2.new(screenPos.X, screenPos.Y) - mousePos).Magnitude
            if distanceToMouse < shortestDistance then
                if S.Aimbot_WallCheck then
                    -- Se il Wall Check è attivo, mira solo se almeno una parte del corpo è visibile
                    if GetVisibility(entityId, character) then
                        target = aimPart
                        shortestDistance = distanceToMouse
                    end
                else
                    -- Wall Check disattivato: mira attraverso i muri
                    target = aimPart
                    shortestDistance = distanceToMouse
                end
            end
        end
    end
 
    for _, player in pairs(Players:GetPlayers()) do
        if player ~= LocalPlayer and player.Character then
            if player.Team ~= LocalPlayer.Team or player.Team == nil then
                CheckTarget(tostring(player.UserId), player.Character)
            end
        end
    end
 
    if S.Aimbot_Target_NPCs then
        for npc in pairs(Tracked_NPCs) do
            if npc.PrimaryPart or npc:FindFirstChild("HumanoidRootPart") then
                CheckTarget(npc, npc)
            end
        end
    end
 
    return target
end
 
local GetClosestTarget=(function()
    local cached,nextSearch,signature=nil,0,""
    return function()
        if not IsAimbotActive() then cached=nil;nextSearch=0;return nil end
        local tag=tostring(S.Aimbot_Target_NPCs)..tostring(S.Aimbot_WallCheck)..tostring(S.Aim_FOV)
            ..tostring(S.Triggerbot_Enabled)..S.Triggerbot_Mode..S.Triggerbot_Target
        local now=os.clock()
        if cached then
            local character=cached.Parent
            local humanoid=character and character:FindFirstChildOfClass("Humanoid")
            local player=character and Players:GetPlayerFromCharacter(character)
            local camera=workspace.CurrentCamera
            local valid=humanoid and humanoid.Health>0 and camera
                and not IsFriendNoTriggerCharacter(character)
                and (player or S.Aimbot_Target_NPCs)
                and (not player or player.Team==nil or player.Team~=LocalPlayer.Team)
            if valid then
                local point,onScreen=camera:WorldToViewportPoint(cached.Position)
                valid=onScreen and (Vector2.new(point.X,point.Y)-UserInputService:GetMouseLocation()).Magnitude<S.Aim_FOV
            end
            if not valid then cached=nil;nextSearch=0 end
        end
        if now>=nextSearch or tag~=signature then
            cached=FindClosestAimTargetNow();nextSearch=now+0.05;signature=tag
        end
        return cached
    end
end)()

-- ==========================================
-- TRIGGERBOT (LEFT / RIGHT CLICK)
-- ==========================================
local TriggerBodyParts = {
    Torso = true,        -- R6
    UpperTorso = true,   -- R15
    LowerTorso = true,
    HumanoidRootPart = true,
}

local TriggerRayParams = RaycastParams.new()
TriggerRayParams.FilterType = Enum.RaycastFilterType.Exclude
TriggerRayParams.IgnoreWater = true
local TriggerInputDown = false
local TriggerHeldContinuous = false
local TriggerPendingRelease
local TriggerRelease
local LastTriggerStatus = ""
local LastStatusTime = -math.huge

local function SetTriggerStatus(message)
    local now = os.clock()
    if message == LastTriggerStatus or now - LastStatusTime < 0.2 then return end
    LastTriggerStatus, LastStatusTime = message, now
    if TriggerStatusLabel then
        TriggerStatusLabel:Set("Triggerbot: " .. message)
    end
end

local TriggerPulseId = 0
local TriggerInputError

local function ReleaseTriggerInput()
    TriggerPulseId = TriggerPulseId + 1
    if not TriggerInputDown then return end
    local release = TriggerRelease
    TriggerInputDown, TriggerRelease = false, nil
    TriggerHeldContinuous = false
    if release then
        SyntheticMouseUntil = os.clock()+0.15
        if not AimWindowFocused then TriggerPendingRelease=release end
        local ok, result = pcall(release)
        if not ok or result == false then TriggerInputError = tostring(result) end
    end
end

-- Release immediately on interruptions; retry after focus returns for focus-gated input APIs.
Native.Connect(UserInputService.WindowFocusReleased,ReleaseTriggerInput)
Native.Connect(UserInputService.TextBoxFocused,ReleaseTriggerInput)
Native.Connect(LocalPlayer.CharacterRemoving,ReleaseTriggerInput)
Native.Connect(UserInputService.WindowFocused,function()
    if TriggerPendingRelease then
        local release=TriggerPendingRelease
        TriggerPendingRelease=nil
        SyntheticMouseUntil=os.clock()+0.15
        local ok,result=pcall(release)
        if not ok or result==false then TriggerInputError=tostring(result) end
    end
end)

local function GetTriggerPosition(camera)
    -- The linked mode uses exactly the same cursor coordinates as the working aimbot.
    if S.Triggerbot_Mode == "With Aimbot" or S.Triggerbot_Mode == "With Aim Assist" then
        return UserInputService:GetMouseLocation()
    end
    local useCenter = S.Triggerbot_AimPoint == "Center"
        or (S.Triggerbot_AimPoint == "Auto"
            and UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter)
    if useCenter then return camera.ViewportSize / 2 end
    return UserInputService:GetMouseLocation()
end

local function IsTriggerWindowActive()
    if not AimWindowFocused then return false end
    if type(isrbxactive) == "function" then
        local ok, active = pcall(isrbxactive)
        if ok and active == false then return false end
    end
    return true
end

local function GetTriggerInputActions(requireHold)
    local method = S.Triggerbot_ClickMethod
    local isLeft = S.Triggerbot_MouseButton == "Left Click"
    local buttonIndex = isLeft and 0 or 1
    -- Assign explicitly so missing left-click functions never fall back to right click.
    local click, press, release = mouse2click, mouse2press, mouse2release
    if isLeft then
        click, press, release = mouse1click, mouse1press, mouse1release
    end
    local buttonName = isLeft and "Left" or "Right"

    if method == "VirtualInputManager" then
        local ok, manager = pcall(function()
            return game:GetService("VirtualInputManager")
        end)
        if not ok then return nil, nil, tostring(manager) end
        return function(x, y)
            manager:SendMouseButtonEvent(x, y, buttonIndex, true, game, 0)
        end, function(x, y)
            manager:SendMouseButtonEvent(x, y, buttonIndex, false, game, 0)
        end
    end
    if method == "Executor Click" then
        if requireHold then return nil,nil,"Hold needs VirtualInputManager or a press/release method" end
        if type(click) ~= "function" then return nil, nil, buttonName .. " click function missing" end
        return function() return click() end
    end
    if method == "Executor Coordinates" then
        if type(press) == "function" and type(release) == "function" then
            return press, release
        end
        if not requireHold and type(click) == "function" then return click end
        return nil, nil, buttonName .. " press/release input functions missing"
    end
    if method == "Executor Press/Release" then
        if type(press) ~= "function" or type(release) ~= "function" then
            return nil, nil, buttonName .. " press/release functions missing"
        end
        return function() return press() end,
            function() return release() end
    end
    return nil, nil, "Unknown click method"
end

local function HasTriggerInput()
    local press = GetTriggerInputActions(S.Triggerbot_FireMode=="Hold")
    return type(press) == "function"
end

local function SendTriggerClick(hold)
    if ConfigLoading then return false,"Config is loading" end
    if TriggerInputDown then return false, "A click is already in progress" end
    if not IsTriggerWindowActive() then return false, "Roblox window is not focused" end
    if UserInputService:GetFocusedTextBox() then return false, "Close the text input first" end
    local camera = workspace.CurrentCamera
    if not camera then return false, "Camera unavailable" end
    local press, release, unavailable = GetTriggerInputActions(hold==true)
    if not press then return false, unavailable end
    if hold and not release then return false,"This input method cannot hold a button" end

    local point = GetTriggerPosition(camera)
    local x, y = math.floor(point.X), math.floor(point.Y)
    TriggerInputError = nil
    -- Mark busy before the call: executor click functions may yield.
    TriggerInputDown = true
    TriggerHeldContinuous = hold==true
    TriggerPulseId = TriggerPulseId + 1
    local pulseId = TriggerPulseId
    TriggerRelease = release and function()
        local rx,ry=x,y
        if hold and workspace.CurrentCamera then
            local current=GetTriggerPosition(workspace.CurrentCamera)
            rx,ry=math.floor(current.X),math.floor(current.Y)
        end
        return release(rx,ry)
    end or nil
    SyntheticMouseButton = S.Triggerbot_MouseButton == "Left Click"
        and Enum.UserInputType.MouseButton1 or Enum.UserInputType.MouseButton2
    SyntheticMouseUntil = os.clock() + 0.15
    local ok, result = pcall(press, x, y)
    if not ok or result == false then
        ReleaseTriggerInput()
        return false, tostring(result)
    end
    if hold then
        return true
    elseif release then
        Native.Delay(0.06, function()
            if pulseId == TriggerPulseId then ReleaseTriggerInput() end
        end)
    else
        ReleaseTriggerInput()
    end
    return true
end

local function DisableTriggerbot(reason)
    S.Triggerbot_Enabled = false
    ReleaseTriggerInput()
    if TriggerbotToggle then TriggerbotToggle:Set(false) end
    Rayfield:Notify({ Title = "Triggerbot unavailable", Content = reason, Duration = 7 })
end

local function GetTriggerHit(camera)
    local point = GetTriggerPosition(camera)
    local originRay = camera:ViewportPointToRay(point.X, point.Y)

    local ignored = { camera }
    if LocalPlayer.Character then table.insert(ignored, LocalPlayer.Character) end
    for _ = 1, 24 do
        TriggerRayParams.FilterDescendantsInstances = ignored
        local result = workspace:Raycast(originRay.Origin, originRay.Direction * 10000, TriggerRayParams)
        if not result then return nil end
        local part = result.Instance
        local accessory = part:FindFirstAncestorOfClass("Accessory")
        if accessory then
            -- Skip decorative accessories, but keep walls and other geometry solid.
            table.insert(ignored, accessory)
        else
            return part
        end
    end
    return nil
end

local function GetTriggerCharacter(part)
    local ancestor = part and part.Parent
    while ancestor and ancestor ~= workspace do
        if ancestor:IsA("Model") then
            local humanoid = ancestor:FindFirstChildOfClass("Humanoid")
            if humanoid then return ancestor, humanoid end
        end
        ancestor = ancestor.Parent
    end
    return nil
end

local LastTriggerTarget
local TriggerReadySince

local function StopTriggerTracking(message)
    LastTriggerTarget = nil
    TriggerReadySince = nil
    LastTriggerClick = -math.huge
    ReleaseTriggerInput()
    SetTriggerStatus(message)
end

local function GetAimbotTriggerPart(camera)
    if not IsAimbotActive() then return nil, "Waiting for aimbot" end
    local part = CurrentAimPart
    if not part or not part.Parent or CurrentAimCamera ~= camera
        or os.clock() - CurrentAimUpdate > 0.15 then
        return nil, "Waiting for aim target"
    end
    local aimPosition = GetAimPosition(part, camera)
    local screen, onScreen = camera:WorldToViewportPoint(aimPosition)
    if not onScreen then return nil, "Aim target off screen" end
    local cursor = UserInputService:GetMouseLocation()
    local distance = (Vector2.new(screen.X, screen.Y) - cursor).Magnitude
    if distance > S.Triggerbot_AimTolerance then
        return nil, string.format("Aiming: %.0f px", distance)
    end

    -- Recheck the selected target itself; seeing a foot does not expose its head.
    local targetCharacter = GetTriggerCharacter(part)
    if not targetCharacter then return nil, "Invalid aim target" end
    local ignored = { camera }
    if LocalPlayer.Character then table.insert(ignored, LocalPlayer.Character) end
    TriggerRayParams.FilterDescendantsInstances = ignored
    local direction = part.Position - camera.CFrame.Position
    local hit = workspace:Raycast(camera.CFrame.Position, direction, TriggerRayParams)
    if not hit or not hit.Instance:IsDescendantOf(targetCharacter) then
        return nil, "Aim target blocked"
    end
    return part
end

local function UpdateTriggerbot()
    if not Native.IsRunning() or Native.IsInteracting() or Native.SystemMenuOpen() or Movement.BlocksCombat() then StopTriggerTracking("Paused");return end
    if ConfigLoading then StopTriggerTracking("Loading config"); return end
    if not S.Triggerbot_Enabled then
        if TriggerHeldContinuous then ReleaseTriggerInput() end
        LastTriggerTarget, TriggerReadySince = nil, nil
        LastTriggerClick = -math.huge
        -- Leave an independent Test Selected Click pulse to finish normally.
        SetTriggerStatus("OFF")
        return
    end
    if TriggerInputError then
        local err = TriggerInputError
        TriggerInputError = nil
        DisableTriggerbot("Mouse release failed: " .. err)
        return
    end
    if not IsTriggerWindowActive() or AimCapturingBind or HUDCapture then
        StopTriggerTracking("Paused")
        return
    end
    if UserInputService:GetFocusedTextBox() then
        StopTriggerTracking("Typing")
        return
    end

    local camera = workspace.CurrentCamera
    local character = LocalPlayer.Character
    local localHumanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not camera or not localHumanoid or localHumanoid.Health <= 0 then
        StopTriggerTracking("Waiting for character")
        return
    end

    local part
    if S.Triggerbot_Mode == "With Aimbot" or S.Triggerbot_Mode == "With Aim Assist" then
        local waiting
        if S.Triggerbot_Mode == "With Aim Assist" then
            part, waiting = GetAimAssistTriggerPart(camera)
        else
            part, waiting = GetAimbotTriggerPart(camera)
        end
        if not part then
            StopTriggerTracking(waiting)
            return
        end
    else
        part = GetTriggerHit(camera)
    end
    local targetCharacter, humanoid = GetTriggerCharacter(part)
    if not targetCharacter or humanoid.Health <= 0 then
        StopTriggerTracking(part and ("Hit: " .. part.Name) or "No hit")
        return
    end
    if IsFriendNoTriggerCharacter(targetCharacter) then
        StopTriggerTracking("FriendNoTrigger: teammate or ignored UserId")
        return
    end
    local player = Players:GetPlayerFromCharacter(targetCharacter)
    if targetCharacter == character or (not player and not S.Triggerbot_Target_NPCs) then
        StopTriggerTracking("Target filtered")
        return
    end

    local matches
    if S.Triggerbot_Mode == "With Aim Assist" then
        matches = part == AssistCurrentPart
    else
        matches = (S.Triggerbot_Target == "Head" and part.Name == "Head")
            or (S.Triggerbot_Target == "Body" and TriggerBodyParts[part.Name] == true)
    end
    if not matches then
        StopTriggerTracking("Hit: " .. part.Name .. " / need " .. S.Triggerbot_Target)
        return
    end

    if LastTriggerTarget ~= part then
        if TriggerHeldContinuous then ReleaseTriggerInput() end
        LastTriggerClick = -math.huge
        LastTriggerTarget = part
        TriggerReadySince = os.clock()
    end
    -- A held physical fire button is already sending input; do not release it with synthetic clicks.
    local clickType = S.Triggerbot_MouseButton == "Left Click"
        and Enum.UserInputType.MouseButton1 or Enum.UserInputType.MouseButton2
    if S.Triggerbot_Mode == "With Aimbot" and S.Aimbot_Activation == "Hold"
        and S.Aimbot_Bind == clickType and AimHeld then
        SetTriggerStatus("Manual fire button held")
        return
    end
    local now = os.clock()
    local delaySeconds = math.max(0, S.Triggerbot_ReactionDelayMs) / 1000
    local remaining = delaySeconds - (now - (TriggerReadySince or now))
    if remaining > 0 then
        SetTriggerStatus(string.format("Delay: %.0f ms", remaining * 1000))
        return
    end
    if S.Triggerbot_FireMode=="Hold" then
        SetTriggerStatus("Holding: "..targetCharacter.Name.." / "..part.Name)
        if not TriggerInputDown then
            local ok,err=SendTriggerClick(true)
            if not ok then DisableTriggerbot("Hold input failed: "..tostring(err)) end
        end
        return
    end
    SetTriggerStatus("Clicking: " .. targetCharacter.Name .. " / " .. part.Name)
    if TriggerInputDown or now - LastTriggerClick < S.Triggerbot_ClickInterval then return end
    LastTriggerClick = now
    local ok, err = SendTriggerClick()
    if not ok then DisableTriggerbot("Mouse input failed: " .. tostring(err)) end
end

-- ==========================================
-- SOFT AIM ASSIST
-- ==========================================
local AssistStatusLabel
local AssistLastStatus = ""
local AssistStatusTime = -math.huge
local AssistDiagnostics = {}
local AssistPartCache = setmetatable({}, {__mode="k"})
local AssistResidual = Vector2.new(0, 0)

local function SetAssistStatus(message)
    local now=os.clock()
    if message==AssistLastStatus or now-AssistStatusTime<0.15 then return end
    AssistLastStatus,AssistStatusTime=message,now
    if AssistStatusLabel then AssistStatusLabel:Set("Assist: "..message) end
end
local AssistCircle
local AssistRayParams = RaycastParams.new()
AssistRayParams.FilterType = Enum.RaycastFilterType.Exclude
AssistRayParams.IgnoreWater = true

local function ResetAimAssist()
    AssistCurrentPart, AssistCurrentCamera = nil, nil
    AssistCurrentUpdate = -math.huge
    AssistResidual = Vector2.new(0, 0)
end

local function AssistActivationHeld()
    if S.Assist_Activation == "Always" or S.Assist_Activation=="Toggle Module" then return true end
    if S.Assist_Activation == "Toggle" then return AssistBindToggled end
    local button = S.Assist_Bind
    if S.Assist_Activation == "Hold Left Click" then button = Enum.UserInputType.MouseButton1 end
    if S.Assist_Activation == "Hold Right Click" then button = Enum.UserInputType.MouseButton2 end
    if SyntheticMouseButton == button and os.clock() <= SyntheticMouseUntil then return false end
    if button == Enum.UserInputType.MouseButton1 or button == Enum.UserInputType.MouseButton2
        or button == Enum.UserInputType.MouseButton3 then
        return UserInputService:IsMouseButtonPressed(button)
    end
    return button ~= Enum.KeyCode.Unknown and UserInputService:IsKeyDown(button)
end

IsAimAssistActive = function()
    return Native.IsRunning() and not Native.IsInteracting() and not Native.SystemMenuOpen() and not Movement.BlocksCombat() and not ConfigLoading and S.Assist_Enabled and AimWindowFocused and not AimCapturingBind and not HUDCapture
        and not IsAimbotActive() and not UserInputService:GetFocusedTextBox()
        and AssistActivationHeld()
end

local function GetAssistPart(character)
    if not character then return nil end
    local cached=AssistPartCache[character]
    if cached and cached.mode==S.Assist_Target and cached.part:IsDescendantOf(character)
        and cached.part:IsA("BasePart") then return cached.part end

    local function namedPart(name)
        local node=character:FindFirstChild(name,true)
        if not node then return nil end
        if node:IsA("BasePart") then return node end
        return node:FindFirstChildWhichIsA("BasePart",true)
    end
    local part
    if S.Assist_Target=="Body" then
        part=namedPart("UpperTorso") or namedPart("Torso") or namedPart("LowerTorso")
            or namedPart("Chest") or namedPart("HumanoidRootPart")
    else
        part=namedPart("Head")
    end
    if part then AssistPartCache[character]={mode=S.Assist_Target,part=part} end
    return part
end

local function AssistPartCandidate(part,camera,cursor)
    if not part or not part.Parent or not part:IsA("BasePart") then return nil,"missing" end
    -- NPC mesh parts can be nested under folders or submodels.
    local character,humanoid=GetTriggerCharacter(part)
    if not character or not humanoid or humanoid.Health<=0 then return nil,"dead" end
    if character==LocalPlayer.Character then return nil,"filtered" end
    if IsFriendNoTriggerCharacter(character) then return nil,"friend" end
    if GetAssistPart(character)~=part then return nil,"missing" end
    local player=Players:GetPlayerFromCharacter(character)
    if not player and not S.Assist_Target_NPCs then return nil,"filtered" end
    if player and player.Team~=nil and player.Team==LocalPlayer.Team then return nil,"filtered" end
    local screen,onScreen=camera:WorldToViewportPoint(part.Position)
    if not onScreen then return nil,"offscreen" end
    local delta=Vector2.new(screen.X,screen.Y)-cursor
    if delta.Magnitude>S.Assist_FOV then return nil,"outside" end
    return delta
end

local function AssistPartVisible(part,camera,targetPoint,rayOrigin)
    local character=GetTriggerCharacter(part)
    if not character then return false end
    local ignored={camera}
    if LocalPlayer.Character then table.insert(ignored,LocalPlayer.Character) end
    local origin=rayOrigin or camera.CFrame.Position
    local direction=(targetPoint or part.Position)-origin
    for _=1,12 do
        AssistRayParams.FilterDescendantsInstances=ignored
        local hit=workspace:Raycast(origin,direction,AssistRayParams)
        -- No hit means no queryable obstruction before the known target point.
        -- The target's own geometry is allowed to have CanQuery=false.
        if not hit then return true end
        if hit.Instance:IsDescendantOf(character) then return true end
        local obstacle=hit.Instance
        if obstacle:IsA("BasePart") and obstacle.CanCollide==false
            and obstacle.Transparency>=0.99 then
            table.insert(ignored,obstacle)
        else
            return false
        end
    end
    return false
end

local function FindAssistTargetNow(camera,cursor)
    AssistDiagnostics={npcs=0,missing=0,dead=0,filtered=0,offscreen=0,outside=0,blocked=0,friend=0}
    for _ in pairs(Tracked_NPCs) do AssistDiagnostics.npcs=AssistDiagnostics.npcs+1 end
    local currentDelta=AssistPartCandidate(AssistCurrentPart,camera,cursor)
    if currentDelta and AssistPartVisible(AssistCurrentPart,camera) then
        return AssistCurrentPart,currentDelta
    end
    local bestPart,bestDelta
    local bestDistance=S.Assist_FOV
    local function consider(character)
        local part=GetAssistPart(character)
        local delta,reason=AssistPartCandidate(part,camera,cursor)
        if not delta then
            AssistDiagnostics[reason]=AssistDiagnostics[reason]+1
            return
        end
        if delta.Magnitude<=bestDistance then
            if AssistPartVisible(part,camera) then
                bestPart,bestDelta,bestDistance=part,delta,delta.Magnitude
            else
                AssistDiagnostics.blocked=AssistDiagnostics.blocked+1
            end
        end
    end
    for _,player in ipairs(Players:GetPlayers()) do
        if player~=LocalPlayer and player.Character then consider(player.Character) end
    end
    if S.Assist_Target_NPCs then
        for npc in pairs(Tracked_NPCs) do consider(npc) end
    end
    return bestPart,bestDelta
end

local FindAssistTarget=(function()
    local cached,nextSearch,signature=nil,0,""
    return function(camera,cursor)
        local now=os.clock()
        local tag=S.Assist_Target..tostring(S.Assist_Target_NPCs)..tostring(S.Assist_FOV)
        if tag~=signature then cached=nil;nextSearch=0;signature=tag end
        if cached then
            local delta=AssistPartCandidate(cached,camera,cursor)
            if not delta then cached=nil;nextSearch=0
            elseif now<nextSearch then return cached,delta end
        elseif now<nextSearch then return nil end
        local delta
        cached,delta=FindAssistTargetNow(camera,cursor)
        nextSearch=now+0.06
        return cached,delta
    end
end)()

-- Intersect the cursor ray with the selected part's oriented bounds.
-- Uses its existing CFrame/Size; no fixed screen-pixel tolerance or expanded hitbox.
local function GetAssistCursorHit(part,camera)
    if not part or not part:IsA("BasePart") then return nil end
    local cursor=UserInputService:GetMouseLocation()
    local ray=camera:ViewportPointToRay(cursor.X,cursor.Y)
    local origin=part.CFrame:PointToObjectSpace(ray.Origin)
    local direction=part.CFrame:VectorToObjectSpace(ray.Direction)
    local half=part.Size*0.5
    local origins={origin.X,origin.Y,origin.Z}
    local directions={direction.X,direction.Y,direction.Z}
    local extents={half.X,half.Y,half.Z}
    local near,far=0,10000
    for axis=1,3 do
        local o,d,h=origins[axis],directions[axis],extents[axis]
        if math.abs(d)<1e-8 then
            if o < -h or o > h then return nil end
        else
            local first,last=(-h-o)/d,(h-o)/d
            if first>last then first,last=last,first end
            near=math.max(near,first)
            far=math.min(far,last)
            if near>far then return nil end
        end
    end
    local distance=near+math.min(0.01,math.max(0,far-near)*0.5)
    return ray.Origin+ray.Direction*distance,ray.Origin
end

local function UpdateAssistCircle(cursor)
    if not (S.Assist_Enabled and S.Assist_ShowFOV) then
        if AssistCircle then AssistCircle.Visible = false end
        return
    end
    if not AssistCircle then
        local ok, circle = pcall(function() return Native.Visuals.new("Circle") end)
        if not ok then
            S.Assist_ShowFOV = false
            return
        end
        AssistCircle = circle
        circle.Thickness = 1
        circle.Color = Color3.fromRGB(105, 195, 255)
        circle.Transparency = 0.7
        circle.Filled = false
    end
    AssistCircle.Position = cursor
    AssistCircle.Radius = S.Assist_FOV
    AssistCircle.Visible = true
end

local function UpdateAimAssist(deltaTime)
    local camera = workspace.CurrentCamera
    local cursor = UserInputService:GetMouseLocation()
    UpdateAssistCircle(cursor)
    local character = LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local paused
    if not S.Assist_Enabled then paused="OFF"
    elseif not camera or not humanoid or humanoid.Health<=0 then paused="Waiting for character"
    elseif HUDCapture or AimCapturingBind then paused="Waiting for bind"
    elseif Movement.BlocksCombat() or Native.SystemMenuOpen() or not AimWindowFocused or UserInputService:GetFocusedTextBox() then paused="Paused"
    elseif IsAimbotActive() then paused="Paused: Aimbot active"
    elseif not AssistActivationHeld() then paused="Waiting for activation" end
    if paused then
        SetAssistStatus(paused)
        ResetAimAssist()
        return
    end
    if type(mousemoverel) ~= "function" then
        S.Assist_Enabled = false
        ResetAimAssist()
        Rayfield:Notify({Title="Aim Assist", Content="mousemoverel() is unavailable.", Duration=5})
        return
    end

    local part, delta = FindAssistTarget(camera, cursor)
    if not part then
        if not S.Assist_Target_NPCs then
            SetAssistStatus("No player target; NPC targeting OFF")
        else
            local d=AssistDiagnostics
            SetAssistStatus(string.format("No target | NPCs %d, missing %d, FOV %d, blocked %d, friends %d",
                d.npcs,d.missing,d.outside+d.offscreen,d.blocked,d.friend))
        end
        ResetAimAssist()
        return
    end
    local targetCharacter=GetTriggerCharacter(part)
    local player=targetCharacter and Players:GetPlayerFromCharacter(targetCharacter)
    SetAssistStatus((player and "Player: " or "NPC: ")..targetCharacter.Name.." / "..part.Name)
    if part ~= AssistCurrentPart then
        AssistResidual = Vector2.new(0, 0)
        AssistCurrentPart = part
    end
    AssistCurrentCamera = camera
    AssistCurrentUpdate = os.clock()
    if delta.Magnitude <= 2 and GetAssistCursorHit(part,camera) then
        AssistResidual = Vector2.new(0, 0)
        return
    end

    -- One speed setting controls both responsiveness and the movement cap.
    -- FOV only determines eligibility; it no longer slows targets near its edge.
    local dt = math.min(math.max(deltaTime or 1/60, 0), 0.05)
    local speed = math.min(100, math.max(1, S.Assist_Speed)) / 100
    local responsiveness = 2 + 38 * speed * speed
    local alpha = 1 - math.exp(-responsiveness * dt)
    local movement = delta * alpha
    local maxMovement = (80 + 1920 * speed) * dt
    if movement.Magnitude > maxMovement then
        movement = movement * (maxMovement / movement.Magnitude)
    end
    -- Preserve subpixel motion for input functions that accept only integer deltas.
    local total = movement + AssistResidual
    local dx = total.X >= 0 and math.floor(total.X) or math.ceil(total.X)
    local dy = total.Y >= 0 and math.floor(total.Y) or math.ceil(total.Y)
    AssistResidual = total - Vector2.new(dx, dy)
    if dx ~= 0 or dy ~= 0 then mousemoverel(dx, dy) end
end

GetAimAssistTriggerPart = function(camera)
    if not IsAimAssistActive() then return nil, "Waiting for aim assist" end
    local part = AssistCurrentPart
    if not part or not part.Parent or AssistCurrentCamera ~= camera
        or os.clock() - AssistCurrentUpdate > 0.15 then
        return nil, "Waiting for assist target"
    end
    local character, humanoid = GetTriggerCharacter(part)
    if not character or not humanoid or humanoid.Health <= 0 then return nil, "Invalid assist target" end
    local hitPoint,rayOrigin=GetAssistCursorHit(part,camera)
    if not hitPoint then return nil,"Crosshair outside selected hitbox" end
    if not AssistPartVisible(part,camera,hitPoint,rayOrigin) then return nil,"Assist target blocked" end
    return part
end

-- Compact active-feature overlay. Badges edit real bindings.
local HUDConfig = { Enabled=true, Scale=1 }
local HUDFrame, HUDRoot, HUDScale, HUDCount
local HUDRows = {}
local HUDConnections = {}
local HUDSelectedFeature = "Aimbot"
local HUDTweenService = game:GetService("TweenService")

local function HUDBindMatches(input,bind)
    return bind and (input.UserInputType==bind
        or (input.UserInputType==Enum.UserInputType.Keyboard and input.KeyCode==bind))
end

local function HUDKeyText(bind)
    if not bind or bind==Enum.KeyCode.Unknown then return "-" end
    local short={MouseButton1="M1",MouseButton2="M2",MouseButton3="M3",
        LeftShift="LSH",RightShift="RSH",LeftControl="CTRL",RightControl="RCTRL",
        LeftAlt="ALT",RightAlt="RALT",Space="SPACE",Backspace="BACK"}
    return short[bind.Name] or string.upper(bind.Name)
end

local function HUDTriggerActive()
    if not Native.IsRunning() or Native.SystemMenuOpen() or Movement.BlocksCombat() or not S.Triggerbot_Enabled then return false end
    if S.Triggerbot_Mode=="With Aimbot" then return IsAimbotActive() end
    if S.Triggerbot_Mode=="With Aim Assist" then return IsAimAssistActive() end
    return not HUDCapture and AimWindowFocused and not UserInputService:GetFocusedTextBox()
end

local HUDFeatures = {
    {id="FreeCam",name="FreeCam",field="FreeCam_Enabled",active=function() return Movement.Active("FreeCam") end},
    {id="NoClip",name="NoClip",field="NoClip_Enabled",active=function() return Movement.Active("NoClip") end},
    {id="InfiniteJump",name="Infinite Jump",field="InfiniteJump_Enabled",active=function() return Movement.Active("InfiniteJump") end},
    {id="Fly",name="Fly",field="Fly_Enabled",active=function() return Movement.Active("Fly") end},
    {id="Speed",name="Speed",field="Speed_Enabled",active=function() return Movement.Active("Speed") end},
    {id="Aimbot",name="Aimbot",active=IsAimbotActive},
    {id="Assist",name="Aim Assist",active=IsAimAssistActive},
    {id="Triggerbot",name="Triggerbot",active=HUDTriggerActive,field="Triggerbot_Enabled"},
    {id="PlayerESP",name="Player ESP",field="ESP_Enabled"},
    {id="PlayerTracers",name="Player Tracers",field="Tracers_Enabled"},
    {id="NPCESP",name="NPC ESP",field="NPC_ESP_Enabled"},
    {id="NPCTracers",name="NPC Tracers",field="NPC_Tracers_Enabled"},
    {id="Fullbright",name="Fullbright",field="Fullbright_Enabled"},
    {id="FriendNoTrigger",name="FriendNoTrigger",field="FriendNoTrigger"},
    {id="NPCScanner",name="NPC Scanner",active=NPCFeaturesNeeded,field="NPCScan_Enabled"},
    {id="Keybinds",name="Keybinds",active=function() return false end},
    {id="AimFOV",name="Aimbot FOV",field="Show_FOV"},
    {id="AssistFOV",name="Assist FOV",active=function() return S.Assist_Enabled and S.Assist_ShowFOV end,field="Assist_ShowFOV"},
}
local HUDFeatureById = {}
for _,feature in ipairs(HUDFeatures) do HUDFeatureById[feature.id]=feature end

local function HUDGetBind(id)
    if id=="Aimbot" then return S.Aimbot_Bind end
    if id=="Assist" then
        if S.Assist_Activation=="Hold Right Click" then return Enum.UserInputType.MouseButton2 end
        if S.Assist_Activation=="Hold Left Click" then return Enum.UserInputType.MouseButton1 end
        if S.Assist_Activation=="Always" then return nil end
        return S.Assist_Bind
    end
    return HUDFeatureBinds[id]
end

local function HUDSetBind(id,bind,asModule)
    if id=="Aimbot" then
        S.Aimbot_Bind=bind or Enum.KeyCode.Unknown
        ResetAimActivation()
        if asModule then Native.Controls["Aimbot Activation"]:Set({"Toggle Module"}) end
        UpdateAimBindLabel()
    elseif id=="Assist" then
        S.Assist_Bind=bind or Enum.KeyCode.Unknown
        local isMouse=bind==Enum.UserInputType.MouseButton1 or bind==Enum.UserInputType.MouseButton2
            or bind==Enum.UserInputType.MouseButton3
        local mode=asModule and "Toggle Module" or (isMouse and "Hold Bind" or "Toggle")
        S.Assist_Activation=mode
        AssistBindToggled=false
        ResetAimAssist()
        if HUDSelectHandles.AssistActivation then HUDSelectHandles.AssistActivation:Set({mode}) end
        if HUDSelectHandles.AssistBindLabel then
            HUDSelectHandles.AssistBindLabel:Set("Assist Bind: "..HUDKeyText(S.Assist_Bind))
        end
    else
        HUDFeatureBinds[id]=bind
    end
    Native.RefreshBinds()
end

HUDArmBind = function(id,asModule)
    if not HUDFeatureById[id] then return end
    AimCapturingBind=false
    local focused=UserInputService:GetFocusedTextBox()
    if focused then focused:ReleaseFocus() end
    HUDCapture={id=id,started=os.clock(),asModule=asModule==true}
    if id=="Aimbot" then ResetAimActivation() end
    Rayfield:Notify({Title="Set Keybind: "..HUDFeatureById[id].name,
        Content="Press a key or mouse button. Esc cancels; Delete clears the bind.",Duration=5})
end

Native.SetBindHandler(function(id) HUDArmBind(id,true) end,function(id) return HUDKeyText(HUDGetBind(id)) end)

table.insert(HUDConnections,Native.Connect(UserInputService.InputBegan,function(input,processed)
    if IsSyntheticMouseInput(input) then return end
    if HUDCapture then
        if os.clock()-HUDCapture.started<0.2 or UserInputService:GetFocusedTextBox() then return end
        if input.KeyCode==Enum.KeyCode.K then
            Rayfield:Notify({Title="Menu key",Content="K opens/closes ClickGUI. Choose another feature key.",Duration=3})
            return
        end
        if input.KeyCode==Enum.KeyCode.Escape then HUDCapture=nil; return end
        local id=HUDCapture.id
        if input.KeyCode==Enum.KeyCode.Delete then
            HUDCapture=nil;HUDSetBind(id,nil);return
        end
        local bind
        if input.UserInputType==Enum.UserInputType.Keyboard and input.KeyCode~=Enum.KeyCode.Unknown then
            bind=input.KeyCode
        elseif input.UserInputType==Enum.UserInputType.MouseButton1
            or input.UserInputType==Enum.UserInputType.MouseButton2
            or input.UserInputType==Enum.UserInputType.MouseButton3 then
            bind=input.UserInputType
        end
        if bind then
            for _,feature in ipairs(HUDFeatures) do
                if feature.id~=id and HUDGetBind(feature.id)==bind then
                    Rayfield:Notify({Title="Key already used",Content=HUDKeyText(bind).." is used by "..feature.name,Duration=3})
                    return
                end
            end
            local asModule=HUDCapture.asModule
            HUDCapture=nil;HUDSetBind(id,bind,asModule)
        end
        return
    end
    if (processed and input.UserInputType~=Enum.UserInputType.Keyboard) or not AimWindowFocused
        or AimCapturingBind or UserInputService:GetFocusedTextBox() then return end
    if input.UserInputType==Enum.UserInputType.Keyboard and input.KeyCode==Enum.KeyCode.K then
        Native.ToggleMenu()
        return
    end
    if Native.SystemMenuOpen() then return end
    if S.Aimbot_Activation=="Toggle Module" and HUDBindMatches(input,S.Aimbot_Bind) then
        if not Native.IsRunning() then Native.Start(true) end
        HUDToggleHandles.Aimbot:Set(not S.Aimbot_Enabled)
    end
    if S.Assist_Activation=="Toggle Module" and HUDBindMatches(input,S.Assist_Bind) then
        if not Native.IsRunning() then Native.Start(true) end
        HUDToggleHandles.Assist:Set(not S.Assist_Enabled)
    end
    if S.Assist_Activation=="Toggle" and HUDBindMatches(input,S.Assist_Bind) then
        if not S.Assist_Enabled then HUDToggleHandles.Assist:Set(true) end
        if not Native.IsRunning() then Native.Start(true) end
        AssistBindToggled=not AssistBindToggled
        ResetAimAssist()
    end
    for _,feature in ipairs(HUDFeatures) do
        if feature.id~="Aimbot" and feature.id~="Assist" and HUDBindMatches(input,HUDFeatureBinds[feature.id]) then
            local handle=feature.id=="Triggerbot" and TriggerbotToggle or HUDToggleHandles[feature.id]
            if handle then
                if not Native.IsRunning() then Native.Start(true) end
                local value
                if feature.id=="Keybinds" then value=HUDConfig.Enabled else value=S[feature.field] end
                handle:Set(not value)
            end
        end
    end
end))

local function HUDMake(class,properties,parent)
    local instance=Instance.new(class)
    for key,value in pairs(properties or {}) do instance[key]=value end
    DeltaLanguage.Track(instance)
    instance.Parent=parent
    return instance
end
local function HUDRound(parent,radius)
    HUDMake("UICorner",{CornerRadius=UDim.new(0,radius)},parent)
end
local function HUDTween(instance,values)
    HUDTweenService:Create(instance,TweenInfo.new(0.14,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),values):Play()
end

local function HUDResetPosition()
    HUDConfig.Position=nil
    if HUDFrame then HUDFrame.Position=UDim2.new(1,-24,0.28,0) end
end

local function HUDRefresh()
    if not HUDFrame then return end
    local count=0
    for _,feature in ipairs(HUDFeatures) do
        local row=HUDRows[feature.id]
        local active=feature.active and feature.active() or (not feature.active and S[feature.field])
        active=active==true
        local badge=HUDKeyText(HUDGetBind(feature.id))
        if feature.id=="Assist" and S.Assist_Activation=="Always" then badge="ON" end
        if feature.id=="Triggerbot" and not HUDGetBind(feature.id) then badge="AUTO" end
        row.badge.Text=HUDCapture and HUDCapture.id==feature.id and "..." or badge
        if active then
            count=count+1
            local y=31+(count-1)*27
            if not row.frame.Visible then
                row.frame.Position=UDim2.new(0,8,0,y+4)
                row.label.TextTransparency=1
                row.frame.Visible=true
                HUDTween(row.label,{TextTransparency=0})
            end
            if row.y~=y then
                row.y=y
                HUDTween(row.frame,{Position=UDim2.new(0,8,0,y)})
            end
        else
            row.frame.Visible=false
            row.y=nil
        end
    end
    local height=38+count*27
    if HUDFrame.Size.Y.Offset~=height then HUDTween(HUDFrame,{Size=UDim2.new(0,220,0,height)}) end
    HUDCount.Text=tostring(count)
    HUDFrame.Visible=Native.IsRunning() and HUDConfig.Enabled
end

local function HUDBuild()
    local playerGui=LocalPlayer:WaitForChild("PlayerGui",10)
    assert(playerGui,"PlayerGui unavailable")
    local old=playerGui:FindFirstChild("CombatKeybindsHUD")
    if old then old:Destroy() end
    HUDRoot=HUDMake("ScreenGui",{Name="CombatKeybindsHUD",ResetOnSpawn=false,
        ZIndexBehavior=Enum.ZIndexBehavior.Sibling})
    Native.MountOverlay(HUDRoot,0)
    HUDFrame=HUDMake("Frame",{Name="Panel",AnchorPoint=Vector2.new(1,0),Position=UDim2.new(1,-24,0.28,0),
        Size=UDim2.new(0,220,0,38),BackgroundColor3=Color3.fromRGB(8,24,35),BackgroundTransparency=0.08,
        BorderSizePixel=0,Visible=false},HUDRoot)
    HUDRound(HUDFrame,10)
    HUDMake("UIStroke",{Color=Color3.fromRGB(35,117,150),Transparency=0.35,Thickness=1},HUDFrame)
    HUDScale=HUDMake("UIScale",{Scale=HUDConfig.Scale},HUDFrame)
    local header=HUDMake("TextButton",{Name="Header",Text="",AutoButtonColor=false,
        BackgroundTransparency=1,Position=UDim2.new(0,0,0,0),Size=UDim2.new(1,0,0,29)},HUDFrame)
    HUDMake("TextLabel",{Text="KEYBINDS",Font=Enum.Font.GothamSemibold,TextSize=11,
        TextColor3=Color3.fromRGB(112,199,234),TextXAlignment=Enum.TextXAlignment.Left,
        BackgroundTransparency=1,Position=UDim2.new(0,12,0,0),Size=UDim2.new(1,-48,1,0)},header)
    HUDCount=HUDMake("TextLabel",{Text="0",Font=Enum.Font.Gotham,TextSize=11,
        TextColor3=Color3.fromRGB(69,133,162),TextXAlignment=Enum.TextXAlignment.Right,
        BackgroundTransparency=1,Position=UDim2.new(1,-36,0,0),Size=UDim2.new(0,24,1,0)},header)
    HUDMake("Frame",{BackgroundColor3=Color3.fromRGB(29,77,98),BackgroundTransparency=0.4,
        BorderSizePixel=0,Position=UDim2.new(0,10,0,28),Size=UDim2.new(1,-20,0,1)},HUDFrame)
    for _,feature in ipairs(HUDFeatures) do
        local row=HUDMake("Frame",{Name=feature.id,BackgroundTransparency=1,Size=UDim2.new(1,-16,0,25),Visible=false},HUDFrame)
        local dot=HUDMake("Frame",{BackgroundColor3=Color3.fromRGB(58,170,211),BorderSizePixel=0,
            Position=UDim2.new(0,5,0,10),Size=UDim2.new(0,5,0,5)},row)
        HUDRound(dot,3)
        local label=HUDMake("TextLabel",{Text=feature.name,Font=Enum.Font.GothamMedium,TextSize=12,
            TextColor3=Color3.fromRGB(94,180,218),TextXAlignment=Enum.TextXAlignment.Left,BackgroundTransparency=1,
            Position=UDim2.new(0,19,0,0),Size=UDim2.new(1,-77,1,0)},row)
        local badge=HUDMake("TextButton",{Text="-",Font=Enum.Font.GothamSemibold,TextSize=10,
            TextColor3=Color3.fromRGB(123,218,249),BackgroundColor3=Color3.fromRGB(20,65,86),
            BackgroundTransparency=0.18,BorderSizePixel=0,Position=UDim2.new(1,-51,0,2),Size=UDim2.new(0,46,0,21)},row)
        HUDRound(badge,6)
        HUDRows[feature.id]={frame=row,label=label,badge=badge}
        local featureId=feature.id
        table.insert(HUDConnections,Native.Connect(badge.Activated,function() HUDArmBind(featureId) end))
    end
    local dragStart,dragPosition
    table.insert(HUDConnections,Native.Connect(header.InputBegan,function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
            dragStart=input.Position;dragPosition=HUDFrame.Position
        end
    end))
    table.insert(HUDConnections,Native.Connect(UserInputService.InputChanged,function(input)
        if dragStart and (input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch) then
            local delta=(input.Position-dragStart)/HUDConfig.Scale
            HUDFrame.Position=UDim2.new(dragPosition.X.Scale,dragPosition.X.Offset+delta.X,
                dragPosition.Y.Scale,dragPosition.Y.Offset+delta.Y)
        end
    end))
    table.insert(HUDConnections,Native.Connect(UserInputService.InputEnded,function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragStart=nil end
    end))
    Native.Connect(HUDRoot.Destroying,function()
        for _,connection in ipairs(HUDConnections) do connection:Disconnect() end
        HUDFrame=nil
    end)
    if HUDConfig.Position then
        local p=HUDConfig.Position;HUDFrame.Position=UDim2.new(p.xs,p.xo,p.ys,p.yo)
    end
    HUDRefresh()
end


