}
local function ConfigWrapTab(tab)
    return setmetatable({}, {__index=function(_,method)
        local original=tab[method]
        if type(original)~="function" then return original end
        return function(_,settings,...)
            local handle=original(tab,settings,...)
            if (method=="CreateToggle" or method=="CreateSlider" or method=="CreateDropdown")
                and type(settings)=="table" and ConfigSpecs[settings.Name] then
                local spec=ConfigSpecs[settings.Name]
                local entry={scope=spec[1],key=spec[2],factor=spec[3] or 1,
                    handle=handle,method=method,range=settings.Range,options=settings.Options}
                table.insert(ConfigControls,entry)
                ConfigEntries[entry.scope.."."..entry.key]=entry
            end
            return handle
        end
    end})
end

