        -- Pause targeting so the test sends exactly one independent click.
        local wasEnabled = S.Triggerbot_Enabled
        S.Triggerbot_Enabled = false
        if TriggerbotToggle then TriggerbotToggle:Set(false) end
        ReleaseTriggerInput()
        Rayfield:Notify({
            Title = "Mouse Click Test",
            Content = "Move into the game and close the menu. One selected mouse click in 2 seconds.",
            Duration = 3,
        })
        Native.Delay(2, function()
            local method = S.Triggerbot_ClickMethod .. " / " .. S.Triggerbot_MouseButton
            local ok, err = SendTriggerClick()
            Native.Delay(0.15, function()
                local releaseError = TriggerInputError
                TriggerInputError = nil
                local content
                if not ok or releaseError then
                    content = method .. ": " .. tostring(err or releaseError)
                else
                    content = method .. ": call returned without error. Check the game response."
                end
                if wasEnabled then content = content .. " Re-enable Triggerbot after the test." end
                Rayfield:Notify({ Title = "Mouse Click Test", Content = content, Duration = 10 })
                warn("Mouse Click Test: " .. content)
            end)
        end)
    end,
})

-- ==========================================
-- MAIN CORE LOOP (RenderStepped)
-- ==========================================
Native.Connect(RunService.RenderStepped,function()
    if not Native.IsRunning() then return end
    CurrentAimPart, CurrentAimCamera = nil, nil
    CurrentAimUpdate = -math.huge
    local cam = workspace.CurrentCamera
    if not LocalPlayer.Character or not LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then return end
    if not cam then return end
 
    -- Aggiorna i filtri del Raycast per non collidere con il proprio corpo o la telecamera
    refreshRayFilter()
 
    local mousePos = UserInputService:GetMouseLocation()
 
    -- FOV
    UpdateAimbotFOV(mousePos)
 
    -- Fullbright
    if S.Fullbright_Enabled then
        Lighting.Ambient = Color3.fromRGB(255, 255, 255)
        Lighting.Brightness = 2
    else
        Lighting.Ambient = OriginalAmbient
        Lighting.Brightness = OriginalBrightness
    end
 
    local visualTime=os.clock()
    if visualTime>=NativeESPNextFrame then
        NativeESPNextFrame=visualTime+1/math.max(5,S.ESP_UpdateFPS)
        NativeESPDrawCount=0
        NativeESPEpoch=NativeESPEpoch+1
        NativeESPDeadline=visualTime+0.002
    -- CRITICAL FIX: Previene i "Ghost ESP" dei cadaveri o dei nemici usciti dal range.
    for id in pairs(ESP_Cache) do HideESP(id) end
 
    if S.ESP_Enabled or S.Tracers_Enabled then
    -- Rendering Giocatori
    for _, player in pairs(Players:GetPlayers()) do
        if player ~= LocalPlayer and player.Character then
            local hrp = player.Character:FindFirstChild("HumanoidRootPart")
            if hrp then
                DrawESP(tostring(player.UserId), player.Character, hrp, player.Name, player.Team, false)
            end
        end
    end
 
    end

    if S.NPC_ESP_Enabled or S.NPC_Tracers_Enabled then
    -- Rendering NPC
    for npc in pairs(Tracked_NPCs) do
        if npc:FindFirstChild("Humanoid") and npc.Humanoid.Health > 0 then
            local hrp = npc:FindFirstChild("HumanoidRootPart")
            if hrp then
                DrawESP(npc, npc, hrp, npc.Name, nil, true)
            end
        end
    end
 
    end

        local removed=0
        for id,cached in pairs(ESP_Cache) do
            if removed<10 and visualTime-(cached.lastRendered or visualTime)>10 then
                ClearEntityESP(id);removed=removed+1
            end
        end
    end

    -- Aimbot 
    if IsAimbotActive() then
        local aimTarget = GetClosestTarget()
        if aimTarget and mousemoverel then
            local aimPos = GetAimPosition(aimTarget, cam)
 
            local screenPos, onScreen = cam:WorldToViewportPoint(aimPos)
            if onScreen then
                local moveX = (screenPos.X - mousePos.X) * S.Aim_Smoothing
                local moveY = (screenPos.Y - mousePos.Y) * S.Aim_Smoothing
                mousemoverel(moveX, moveY)
                CurrentAimPart, CurrentAimCamera = aimTarget, cam
                CurrentAimUpdate = os.clock()
            end
        end
    end
end)

-- Independent from ESP/aimbot: their errors cannot skip trigger detection.
Native.Connect(RunService.Heartbeat,function()
    local ok, err = pcall(UpdateTriggerbot)
    if not ok then
        ReleaseTriggerInput()
        S.Triggerbot_Enabled = false
        if TriggerbotToggle then TriggerbotToggle:Set(false) end
        Rayfield:Notify({
            Title = "Triggerbot error",
            Content = tostring(err),
            Duration = 10,
        })
        warn("Triggerbot: " .. tostring(err))
    end
end)


Native.Connect(RunService.RenderStepped,function(deltaTime)
    if not Native.IsRunning() then return end
    local ok, err = pcall(UpdateAimAssist, deltaTime)
    if not ok then
        S.Assist_Enabled = false
        ResetAimAssist()
        if AssistCircle then AssistCircle.Visible = false end
        warn("Aim Assist: " .. tostring(err))
        Rayfield:Notify({Title="Aim Assist error", Content=tostring(err), Duration=8})
    end
end)


