-- Config files contain JSON data only; they are never evaluated as Lua.
local ConfigHttp=game:GetService("HttpService")
local ConfigRoot="DEV_HUB"
local ConfigFolder=ConfigRoot.."/configs"
local ConfigMeta=ConfigRoot.."/autoload.json"
local ConfigSelected,ConfigName,ConfigAutoName=nil,"",nil
local ConfigDropdown,ConfigNameInput,ConfigStatusLabel,ConfigAutoLabel
local function ConfigStatus(text)
    if ConfigStatusLabel then ConfigStatusLabel:Set(text) end
end
local function ConfigNotify(text)
    ConfigStatus(text)
    Rayfield:Notify({Title="Config",Content=text,Duration=6})
end
local function ConfigValidName(value)
    assert(type(value)=="string","Enter a config name")
    local name=value:match("^%s*(.-)%s*$")
    assert(#name>0 and #name<=80,"Name must contain 1–80 bytes")
    assert(not name:find('[<>:"/\\|?*%c]') and not name:find("..",1,true),"Invalid characters in config name")
    assert(name:sub(-1)~=".","Name cannot end with a dot")
    local device=string.upper(name:match("^[^.]+") or name)
    assert(device~="CON" and device~="PRN" and device~="AUX" and device~="NUL"
        and not device:match("^COM[1-9]$") and not device:match("^LPT[1-9]$"),"Reserved config name")
    return name
end
local function ConfigPath(name) return ConfigFolder.."/"..ConfigValidName(name)..".json" end
local function ConfigStorage()
    for _,name in ipairs({"readfile","writefile","listfiles","isfile","isfolder","makefolder","delfile"}) do
        local api=({readfile=readfile,writefile=writefile,listfiles=listfiles,isfile=isfile,
            isfolder=isfolder,makefolder=makefolder,delfile=delfile})[name]
        assert(type(api)=="function","Filesystem API unavailable: "..name)
    end
    if not isfolder(ConfigRoot) then makefolder(ConfigRoot) end
    if not isfolder(ConfigFolder) then makefolder(ConfigFolder) end
    assert(isfolder(ConfigFolder),"Config folder could not be created")
end
local function ConfigReadJSON(path)
    local text=readfile(path)
    assert(type(text)=="string" and #text<=131072,"Invalid or oversized config file")
    local data=ConfigHttp:JSONDecode(text)
    assert(type(data)=="table","Invalid config JSON")
    return data
end
local function ConfigWriteJSON(path,data)
    local text=ConfigHttp:JSONEncode(data)
    writefile(path,text)
    assert(isfile(path) and readfile(path)==text,"File write could not be verified")
end
local function ConfigEncodeBind(bind)
    if not bind then return nil end
    local mouse=bind==Enum.UserInputType.MouseButton1 or bind==Enum.UserInputType.MouseButton2 or bind==Enum.UserInputType.MouseButton3
    return {group=mouse and "UserInputType" or "KeyCode",name=bind.Name}
end
local function ConfigDecodeBind(data)
    assert(type(data)=="table" and type(data.name)=="string","Invalid bind")
    assert(data.group=="KeyCode" or data.group=="UserInputType","Invalid bind group")
    if data.group=="UserInputType" then
        assert(data.name=="MouseButton1" or data.name=="MouseButton2" or data.name=="MouseButton3","Invalid mouse bind")
    end
    local ok,value=pcall(function() return Enum[data.group][data.name] end)
    assert(ok and value and value.Name==data.name,"Unknown bind: "..data.name)
    -- K is reserved for ClickGUI, including when restoring older configs.
    if value==Enum.KeyCode.K then return Enum.KeyCode.Unknown end
    return value
end
local function ConfigSnapshot()
    local settings={}
    for key,value in pairs(S) do
        if key=="Aimbot_Bind" or key=="Assist_Bind" then settings[key]=ConfigEncodeBind(value)
        elseif value==math.huge then settings[key]={number="infinity"}
        else settings[key]=value end
    end
    local binds={}
    for id,bind in pairs(HUDFeatureBinds) do binds[id]=ConfigEncodeBind(bind) end
    local hud={enabled=HUDConfig.Enabled,scale=HUDConfig.Scale}
    if HUDFrame then
        local p=HUDFrame.Position
        hud.position={xs=p.X.Scale,xo=p.X.Offset,ys=p.Y.Scale,yo=p.Y.Offset}
    elseif HUDConfig.Position then
        local p=HUDConfig.Position;hud.position={xs=p.xs,xo=p.xo,ys=p.ys,yo=p.yo}
    end
    return {version=1,settings=settings,binds=binds,hud=hud,friends=Friends.Export(),
        activation={aim=AimToggled,assist=AssistBindToggled}}
end
local function ConfigValidate(data)
    assert(data.version==1 and type(data.settings)=="table","Unsupported config format")
    local result={settings={},binds={},hud={enabled=true,scale=1},activation={aim=false,assist=false}}
    for key,default in pairs(ConfigDefaults) do
        local value=data.settings[key]
        if value==nil then value=default
        elseif key=="Aimbot_Bind" or key=="Assist_Bind" then value=ConfigDecodeBind(value)
        elseif default==math.huge and type(value)=="table" and value.number=="infinity" then value=math.huge
        else
            assert(type(value)==type(default),"Wrong setting type: "..key)
            if type(value)=="number" then assert(value==value and value~=math.huge and value~=-math.huge,"Invalid number: "..key) end
        end
        local entry=ConfigEntries["settings."..key]
        if entry and entry.range then
            assert(value*entry.factor>=entry.range[1] and value*entry.factor<=entry.range[2],"Setting outside range: "..key)
        elseif entry and entry.options then
            local allowed=false
            for _,option in ipairs(entry.options) do if option==value then allowed=true end end
            assert(allowed,"Invalid option: "..key)
        end
        result.settings[key]=value
    end
    assert(data.binds==nil or type(data.binds)=="table","Invalid feature binds")
    for id,bind in pairs(data.binds or {}) do
        if HUDFeatureById[id] and id~="Aimbot" and id~="Assist" then result.binds[id]=ConfigDecodeBind(bind) end
    end
    if data.hud then
        assert(type(data.hud)=="table" and type(data.hud.enabled)=="boolean","Invalid HUD config")
        assert(type(data.hud.scale)=="number" and data.hud.scale>=0.7 and data.hud.scale<=1.5,"Invalid HUD scale")
        result.hud.enabled,result.hud.scale=data.hud.enabled,data.hud.scale
        if data.hud.position then
            local p=data.hud.position
            assert(type(p)=="table","Invalid HUD position")
            for _,key in ipairs({"xs","xo","ys","yo"}) do
                assert(type(p[key])=="number" and p[key]==p[key] and math.abs(p[key])<100000,"Invalid HUD position")
            end
            result.hud.position={xs=p.xs,xo=p.xo,ys=p.ys,yo=p.yo}
        end
    end
    if data.activation then
        assert(type(data.activation)=="table" and type(data.activation.aim)=="boolean"
            and type(data.activation.assist)=="boolean","Invalid activation state")
        result.activation=data.activation
    end
    if result.settings.FreeCam_Enabled then result.settings.Fly_Enabled=false end
    result.friends=Friends.Validate(data.friends)
    return result
end
local function ConfigApplyValues(data)
    Movement.StopAll()
    ReleaseTriggerInput()
    StopTriggerTracking("Loading config")
    ResetAimActivation();ResetAimAssist();HUDCapture=nil;AimCapturingBind=false
    -- Configure controls first, then enabled switches, to minimize transient intermediate states.
    for pass=1,2 do
        for _,entry in ipairs(ConfigControls) do
            local value=data[entry.scope][entry.key]
            local toggle=entry.method=="CreateToggle"
            if value~=nil and ((pass==2 and toggle) or (pass==1 and not toggle)) then
                if type(value)=="number" then value=value*entry.factor end
                entry.handle:Set(entry.method=="CreateDropdown" and {value} or value)
            end
        end
    end
    Friends.Replace(data.friends)
    -- Callbacks can reset related values; restore the validated source of truth last.
    for key,value in pairs(data.settings) do S[key]=value end
    HUDFeatureBinds={}
    for id,bind in pairs(data.binds) do HUDFeatureBinds[id]=bind end
    HUDConfig.Enabled,HUDConfig.Scale=data.hud.enabled,data.hud.scale
    HUDConfig.Position=data.hud.position
    if HUDScale then HUDScale.Scale=HUDConfig.Scale end
    if HUDFrame and data.hud.position then
        local p=data.hud.position;HUDFrame.Position=UDim2.new(p.xs,p.xo,p.ys,p.yo)
    end
    UpdateAimBindLabel()
    if HUDSelectHandles.AssistBindLabel then HUDSelectHandles.AssistBindLabel:Set("Assist Bind: "..HUDKeyText(S.Assist_Bind)) end
    AimHeld=false
    AimToggled=S.Aimbot_Enabled and S.Aimbot_Activation=="Toggle" and data.activation.aim
    AssistBindToggled=S.Assist_Enabled and S.Assist_Activation=="Toggle" and data.activation.assist
    NPCScanState.restart=true
end
local function ConfigApply(payload)
    local data=ConfigValidate(payload)
    local previous=ConfigValidate(ConfigSnapshot())
    ConfigLoading=true
    local ok,err=pcall(ConfigApplyValues,data)
    if not ok then pcall(ConfigApplyValues,previous) end
    ConfigLoading=false
    HUDRefresh()
    assert(ok,"Config load failed: "..tostring(err))
end
local function ConfigReadAuto()
    if not isfile(ConfigMeta) then return nil end
    local meta=ConfigReadJSON(ConfigMeta)
    if meta.name==false or meta.name==nil then return nil end
    return ConfigValidName(meta.name)
end
local function ConfigSetAuto(name)
    ConfigWriteJSON(ConfigMeta,{version=1,name=name or false})
    ConfigAutoName=name
    if ConfigAutoLabel then ConfigAutoLabel:Set("Auto load: "..(name or "disabled")) end
end
local function ConfigRefresh()
    ConfigStorage()
    local names={}
    for _,path in ipairs(listfiles(ConfigFolder)) do
        local name=tostring(path):gsub("\\","/"):match("([^/]+)%.json$")
        if name then
            local ok,valid=pcall(ConfigValidName,name)
            if ok and isfile(ConfigPath(valid)) then table.insert(names,valid) end
        end
    end
    table.sort(names,function(a,b) return a:lower()<b:lower() end)
    local selected
    for _,name in ipairs(names) do if name==ConfigSelected then selected=name end end
    local target=selected or names[1]
    ConfigSelected=target
    ConfigDropdown:Refresh(#names>0 and names or {"(none)"})
    ConfigDropdown:Set({target or "(none)"})
    ConfigAutoName=ConfigReadAuto()
    ConfigAutoLabel:Set("Auto load: "..(ConfigAutoName or "disabled"))
    return names
end
local function ConfigNeedSelected()
    assert(ConfigSelected and isfile(ConfigPath(ConfigSelected)),"Select an existing config")
    return ConfigSelected
end
local function ConfigAction(callback)
    local ok,err=pcall(function() ConfigStorage();callback() end)
    if not ok then ConfigLoading=false;ConfigNotify(tostring(err)) end
end
local function ConfigLoad(name)
    ConfigApply(ConfigReadJSON(ConfigPath(name)))
    ConfigNotify("Loaded: "..name)
end

