    Content="Создай конфиг после настройки функций. Save Selected обновляет выбранный; Load Selected загружает его. Для переименования введи новое имя в Config Name и нажми Rename Selected. Set as Auto Load восстанавливает выбранный конфиг при следующем запуске. Нужна поддержка файлового API среды запуска."})
ConfigTab:CreateSection("Config Files")
ConfigNameInput=ConfigTab:CreateInput({Name="Config Name",PlaceholderText="My config",CurrentValue="",RemoveTextAfterFocusLost=false,
    Callback=function(text) ConfigName=text end})
ConfigDropdown=ConfigTab:CreateDropdown({Name="Saved Configs",Options={"(none)"},CurrentOption={"(none)"},MultipleOptions=false,
    Callback=function(options)
        local name=type(options)=="table" and options[1] or options
        ConfigSelected=name~="(none)" and name or nil
        if ConfigSelected and ConfigNameInput then ConfigNameInput:Set(ConfigSelected) end
    end})
ConfigTab:CreateButton({Name="Create Config",Callback=function() ConfigAction(function()
    local name=ConfigValidName(ConfigName)
    assert(not isfile(ConfigPath(name)),"Config already exists; use Save Selected")
    ConfigWriteJSON(ConfigPath(name),ConfigSnapshot())
    ConfigSelected=name;ConfigRefresh();ConfigNotify("Created: "..name)
end) end})
ConfigTab:CreateButton({Name="Save Selected",Callback=function() ConfigAction(function()
    local name=ConfigNeedSelected();ConfigWriteJSON(ConfigPath(name),ConfigSnapshot());ConfigNotify("Saved: "..name)
end) end})
ConfigTab:CreateButton({Name="Load Selected",Callback=function() ConfigAction(function() ConfigLoad(ConfigNeedSelected()) end) end})
ConfigTab:CreateButton({Name="Rename Selected",Callback=function() ConfigAction(function()
    local old=ConfigNeedSelected();local name=ConfigValidName(ConfigName)
    assert(old:lower()~=name:lower(),"Enter a different name")
    assert(not isfile(ConfigPath(name)),"That config name already exists")
    local text=readfile(ConfigPath(old));writefile(ConfigPath(name),text)
    assert(isfile(ConfigPath(name)) and readfile(ConfigPath(name))==text,"Rename copy could not be verified")
    if ConfigReadAuto()==old then ConfigSetAuto(name) end
    delfile(ConfigPath(old));assert(not isfile(ConfigPath(old)),"Old config could not be removed; both copies were retained")
    ConfigSelected=name;ConfigRefresh();ConfigNotify("Renamed: "..name)
end) end})
ConfigTab:CreateButton({Name="Delete Selected",Callback=function() ConfigAction(function()
    local name=ConfigNeedSelected()
    delfile(ConfigPath(name));assert(not isfile(ConfigPath(name)),"Config could not be deleted")
    if ConfigReadAuto()==name then ConfigSetAuto(nil) end
    ConfigSelected=nil;ConfigRefresh();ConfigNotify("Deleted: "..name)
end) end})
ConfigTab:CreateButton({Name="Refresh List",Callback=function() ConfigAction(function() ConfigRefresh();ConfigStatus("Config list refreshed") end) end})
ConfigTab:CreateSection("Auto Load")
ConfigAutoLabel=ConfigTab:CreateLabel("Auto load: disabled")
ConfigTab:CreateButton({Name="Set as Auto Load",Callback=function() ConfigAction(function()
    local name=ConfigNeedSelected();ConfigSetAuto(name);ConfigNotify("Auto load: "..name)
end) end})
ConfigTab:CreateButton({Name="Disable Auto Load",Callback=function() ConfigAction(function()
    ConfigSetAuto(nil);ConfigNotify("Auto load disabled")
end) end})
ConfigStatusLabel=ConfigTab:CreateLabel("Config storage: waiting")

Native.Delay(1,function()
    local ok,err=pcall(function()
        ConfigRefresh()
        ConfigStatus("Delta Client configs ready")
        local name=ConfigReadAuto()
        if name then
            assert(isfile(ConfigPath(name)),"Auto-load config is missing: "..name)
            ConfigSelected=name;ConfigDropdown:Set({name});ConfigLoad(name)
        end
    end)
    if not ok then ConfigLoading=false;ConfigStatus("Config unavailable: "..tostring(err)) end
end)


Native.SetPause(function()
    Movement.StopAll()
    Friends.Hide()
    ReleaseTriggerInput()
    StopTriggerTracking("Paused")
    ResetAimActivation();ResetAimAssist()
    AssistBindToggled=false
    if HUDFrame then HUDFrame.Visible=false end
    Lighting.Ambient=OriginalAmbient
    Lighting.Brightness=OriginalBrightness
end)
Native.SetShutdown(function()
    Native.PauseCleanup()
    if HUDRoot then HUDRoot:Destroy() end
end)

Native.Connect(RunService.RenderStepped,function()
    ProjectCachedESP()
    Native.FlushVisuals()
end)

Native.SetStart(function()
    if HUDConfig.Enabled and not HUDFrame then HUDBuild() end
    HUDRefresh()
end)

-- Inspect at most one cursor ray every 100 ms; no player/map traversal each frame.
Native.Connect(RunService.Heartbeat,function()
    local ok,err=pcall(Friends.Update,Native.IsRunning() and AimWindowFocused and not HUDCapture and not AimCapturingBind and not ConfigLoading)
    if not ok then
        S.TargetInfo_Enabled=false;Friends.Hide()
        warn("Target ID: "..tostring(err))
    end
end)

Movement.SetGuard(function() return AimCapturingBind or HUDCapture~=nil end)
Movement.Init()

-- DELTA CLIENT RUNTIME RETURN
return Native
end

local DeltaGate=(function()
    local API={ttl=3*24*60*60,url="https://discord.gg/MJAjbSvC"}
    local expected="Delta1"
    function API.Validate(record,now,userId)
        if type(record)~="table" or record.version~=1 or record.product~="DeltaClient" or record.userId~=userId then return false end
        local issued,expires=record.issuedAt,record.expiresAt
        return type(issued)=="number" and type(expires)=="number" and issued==math.floor(issued)
            and expires==math.floor(expires) and issued<=now and expires-issued==API.ttl and now<expires
    end
    function API.Start(launch)
        local players=game:GetService("Players")
        local inputService=game:GetService("UserInputService")
        local run=game:GetService("RunService")
        local player=players.LocalPlayer
        assert(player,"Join a game before running Delta Client")
        local playerGui=player:WaitForChild("PlayerGui",10)
        assert(playerGui,"PlayerGui unavailable")
        local parents={}
        pcall(function() local core=game:GetService("CoreGui");if core then parents[#parents+1]=core end end)
        parents[#parents+1]=playerGui
        local function removeOld()
            for _,parent in ipairs(parents) do
                for _,name in ipairs({"DeltaClientGate","DEV_HUB_NATIVE"}) do
                    pcall(function() local old=parent:FindFirstChild(name);if old then old:Destroy() end end)
                end
            end
        end
        removeOld()
        local disposed=false
        local granting=false
        local app,license,closingApp
        local connections={}
        local frame,keyInput,message,verifyButton,getButton
        local cursor
        local function connect(signal,callback)
            local c=signal:Connect(function(...) if not disposed then return callback(...) end end)
            connections[#connections+1]=c;return c
        end
        local function make(class,properties,parent)
            local object=Instance.new(class)
            for k,v in pairs(properties) do object[k]=v end
            DeltaLanguage.Track(object)
            object.Parent=parent;return object
        end
        local root=make("ScreenGui",{Name="DeltaClientGate",ResetOnSpawn=false,Enabled=false,DisplayOrder=100020,
            ZIndexBehavior=Enum.ZIndexBehavior.Sibling})
        local mounted=false
        for _,parent in ipairs(parents) do
            if pcall(function() root.Parent=parent end) and root.Parent==parent then mounted=true;break end
        end
        assert(mounted,"Unable to mount Delta Client key window")
        local function restoreCursor()
            if cursor then
                pcall(function() inputService.MouseBehavior=cursor.behavior;inputService.MouseIconEnabled=cursor.icon end)
                cursor=nil
            end
        end
        local function stopApp()
            if not app then return end
            closingApp=true
            pcall(function() app.Window():Destroy() end)
            closingApp=false;app=nil
        end
        root.Destroying:Connect(function()
            if disposed then return end
            disposed=true
            for _,c in ipairs(connections) do c:Disconnect() end
            stopApp();restoreCursor()
        end)
        local function label(parent,text,x,y,w,h,size)
            return make("TextLabel",{Text=text,Position=UDim2.new(0,x,0,y),Size=UDim2.new(0,w,0,h),
                BackgroundTransparency=1,Font=Enum.Font.Gotham,TextSize=size or 12,TextWrapped=true,
                TextColor3=Color3.fromRGB(133,190,216),TextXAlignment=Enum.TextXAlignment.Left},parent)
        end
        local function button(text,x,y,w,callback)
            local b=make("TextButton",{Text=text,Position=UDim2.new(0,x,0,y),Size=UDim2.new(0,w,0,38),
                BackgroundColor3=Color3.fromRGB(18,62,82),BorderSizePixel=0,Font=Enum.Font.GothamSemibold,
                TextSize=13,TextColor3=Color3.fromRGB(133,220,251)},frame)
            make("UICorner",{CornerRadius=UDim.new(0,8)},b)
            connect(b.Activated,callback);return b
        end
        local function openInvite()
            local copied=false
            local copy=setclipboard or toclipboard
            if type(copy)=="function" then copied=pcall(copy,API.url) end
            local opened=false
            local open=openurl or open_url
            if type(open)=="function" then local ok,result=pcall(open,API.url);opened=ok and result~=false end
            if not opened then
                local ok,result=pcall(function() return game:GetService("GuiService"):OpenBrowserWindow(API.url) end)
                opened=ok and result~=false
            end
            if not opened then
                local ok,result=pcall(function() return game:GetService("BrowserService"):OpenBrowserWindow(API.url) end)
                opened=ok and result~=false
            end
            message.Text=opened and "Discord invite opened."
                or copied and "Invite copied. Paste it into your browser."
                or "This environment cannot open Discord or copy the invite."
        end
        local show,verify
        local function grant(record,saved)
            if disposed or granting then return end
            granting=true;license=record
            if message then message.Text="Key accepted. Opening Delta Client..." end
            root.Enabled=false;restoreCursor()
            local ok,result=pcall(launch)
            if not ok then
                for _,parent in ipairs(parents) do pcall(function() local old=parent:FindFirstChild("DEV_HUB_NATIVE");if old then old:Destroy() end end) end
                granting=false;license=nil
                show("Startup failed. Check F9 for Delta Client details, then try Verify again.")
                warn("Delta Client startup: "..tostring(result));return
            end
            app=result
            connect(app.Window().Destroying,function() if not closingApp then root:Destroy() end end)
            if not saved then app.Menu:Notify({Title="Delta Client activation",Content="Key accepted for this session. File storage is unavailable; the next launch will ask again.",Duration=9}) end
        end
        verify=function()
            if disposed or granting then return end
            local text=keyInput.Text:gsub("^%s+",""):gsub("%s+$","")
            if text~=expected then message.Text="Incorrect key. Check the spelling and try again.";return end
            local now=os.time()
            local record={version=1,product="DeltaClient",userId=DeltaStorage.UserId(),issuedAt=now,expiresAt=now+API.ttl}
            local saved=DeltaStorage.Write("activation.json",record)
            grant(record,saved)
        end
        show=function(text)
            if disposed then return end
            if not cursor then cursor={behavior=inputService.MouseBehavior,icon=inputService.MouseIconEnabled} end
            inputService.MouseBehavior=Enum.MouseBehavior.Default;inputService.MouseIconEnabled=true
            root.Enabled=true
            if not frame then
                frame=make("Frame",{Name="KeyWindow",AnchorPoint=Vector2.new(.5,.5),Position=UDim2.new(.5,0,.5,0),
                    Size=UDim2.new(0,460,0,350),BackgroundColor3=Color3.fromRGB(8,24,35),BorderSizePixel=0},root)
                make("UICorner",{CornerRadius=UDim.new(0,14)},frame)
                make("UIStroke",{Color=Color3.fromRGB(47,113,149),Transparency=.25,Thickness=1},frame)
                local camera=workspace.CurrentCamera
                local size=camera and camera.ViewportSize
                local scale=size and size.X>0 and size.Y>0 and math.min(1,size.X/500,size.Y/390) or 1
                make("UIScale",{Scale=scale},frame)
                DeltaBrand.Attach(frame,UDim2.new(0,184,0,14),UDim2.new(0,92,0,50),make)
                local title=label(frame,"Delta Client",24,69,412,30,22);title.Font=Enum.Font.GothamSemibold
                title.TextXAlignment=Enum.TextXAlignment.Center
                label(frame,"KEY SYSTEM",24,103,412,18,11).TextXAlignment=Enum.TextXAlignment.Center
                keyInput=make("TextBox",{Name="KeyInput",Text="",PlaceholderText="Enter your key",ClearTextOnFocus=false,
                    Position=UDim2.new(0,24,0,135),Size=UDim2.new(0,412,0,42),BackgroundColor3=Color3.fromRGB(15,42,58),
                    BorderSizePixel=0,Font=Enum.Font.Gotham,TextSize=14,TextColor3=Color3.fromRGB(211,232,245)},frame)
                make("UICorner",{CornerRadius=UDim.new(0,8)},keyInput)
                verifyButton=button("Verify",24,191,200,function() verify() end);verifyButton.Modal=true
                getButton=button("Get Key",236,191,200,openInvite)
                message=label(frame,"",24,246,412,58,12)
                label(frame,"Activation remembered for 72 hours on this device.",24,319,412,20,10)
                button("X",416,8,28,function() root:Destroy() end).Size=UDim2.new(0,28,0,28)
                connect(keyInput.FocusLost,function(enter) if enter then verify() end end)
            end
            keyInput.Text="";message.Text=text or "Enter the key to open Delta Client."
        end
        local elapsed=0
        connect(run.Heartbeat,function(dt)
            elapsed=elapsed+(dt or 1/60)
            if elapsed<1 then return end
            elapsed=0
            if license and not API.Validate(license,os.time(),DeltaStorage.UserId()) then
                stopApp();license=nil;granting=false
                show("Activation expired. Enter your key again.")
            end
        end)
        local cached=DeltaStorage.Read("activation.json")
        if API.Validate(cached,os.time(),DeltaStorage.UserId()) then grant(cached,true) else show() end
        return {Root=root,Input=function() return keyInput end,Verify=function() verify() end,
            GetKey=openInvite,Message=function() return message end,App=function() return app end,
            License=function() return license end,Disposed=function() return disposed end}
    end
    return API
end)()
local DeltaSession=DeltaGate.Start(launchDeltaClient)
